VALUES ('doc-09-mitre-attack-p0-4845', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-17T14:05:09.788Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Operation Dream Job](https://attack.mitre.org/campaigns/C0022), [Lazarus Group](https://attack.mitre.org/groups/G0032) used [Torisma](https://attack.mitre.org/software/S0678) to actively monitor for new drives and remote desktop connections on an infected system.(Citation: McAfee Lazarus Jul 2020)(Citation: McAfee Lazarus Nov 2020)", "external_references": [{"description": "Beek, C. (2020, November 5). Operation North Star: Behind The Scenes. Retrieved December 20, 2021.", "source_name": "McAfee Lazarus Nov 2020", "url": "https://www.mcafee.com/blogs/other-blogs/mcafee-labs/operation-north-star-behind-the-scenes/"}, {"description": "Cashman, M. (2020, July 29). Operation North Star Campaign. Retrieved December 20, 2021.", "source_name": "McAfee Lazarus Jul 2020", "url": "https://www.mcafee.com/blogs/other-blogs/mcafee-labs/operation-north-star-a-job-offer-thats-too-good-to-be-true/?hilite=%27Operation%27%2C%27North%27%2C%27Star%27"}], "id": "relationship--5687f6c6-f749-456e-a7fe-179017d50e9b", "modified": "2026-07-31T21:14:22.590Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--0257b35b-93ef-4a70-80dd-ad5258e6045b", "spec_version": "2.1", "target_ref": "malware--0715560d-4299-4e84-9e20-6e80ab57e4f2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4845', 0, 104, '09-mitre-attack', 'retrieved', '02DB448DEFAC94619B80302FD9BDB86CEAFB57C14F5FEFE6F2D68007D8051831', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
