VALUES ('doc-09-mitre-attack-p0-4870', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-17T14:51:42.500Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Operation Dream Job](https://attack.mitre.org/campaigns/C0022), [Lazarus Group](https://attack.mitre.org/groups/G0032) uses HTTP and HTTPS to contact actor-controlled C2 servers.(Citation: McAfee Lazarus Jul 2020) ", "external_references": [{"description": "Cashman, M. (2020, July 29). Operation North Star Campaign. Retrieved December 20, 2021.", "source_name": "McAfee Lazarus Jul 2020", "url": "https://www.mcafee.com/blogs/other-blogs/mcafee-labs/operation-north-star-a-job-offer-thats-too-good-to-be-true/?hilite=%27Operation%27%2C%27North%27%2C%27Star%27"}], "id": "relationship--b7362262-2738-4d3f-a993-c116557a4eaa", "modified": "2026-07-31T21:14:22.829Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--0257b35b-93ef-4a70-80dd-ad5258e6045b", "spec_version": "2.1", "target_ref": "attack-pattern--df8b2a25-8bdf-4856-953c-a04372b1c161", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4870', 0, 71, '09-mitre-attack', 'retrieved', 'C6B123C4C0A99736F2647E9798BF678BAA65305AC8038A4343F44CEE8627D236', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
