VALUES ('doc-09-mitre-attack-p0-4871', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-17T15:26:43.132Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Operation Dream Job](https://attack.mitre.org/campaigns/C0022), [Lazarus Group](https://attack.mitre.org/groups/G0032) used a custom build of open-source command-line dbxcli to exfiltrate stolen data to Dropbox.(Citation: ESET Lazarus Jun 2020)(Citation: ClearSky Lazarus Aug 2020)", "external_references": [{"description": "Breitenbacher, D and Osis, K. (2020, June 17). OPERATION IN(TER)CEPTION: Targeted Attacks Against European Aerospace and Military Companies. Retrieved December 20, 2021.", "source_name": "ESET Lazarus Jun 2020", "url": "https://www.welivesecurity.com/wp-content/uploads/2020/06/ESET_Operation_Interception.pdf"}, {"description": "ClearSky Research Team. (2020, August 13). Operation ''Dream Job'' Widespread North Korean Espionage Campaign. Retrieved December 20, 2021.", "source_name": "ClearSky Lazarus Aug 2020", "url": "https://www.clearskysec.com/wp-content/uploads/2020/08/Dream-Job-Campaign.pdf"}], "id": "relationship--b8458076-fd1f-48e1-a637-57690c4fe59d", "modified": "2026-07-31T21:14:22.842Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--0257b35b-93ef-4a70-80dd-ad5258e6045b", "spec_version": "2.1", "target_ref": "attack-pattern--bf1b6176-597c-4600-bfcd-ac989670f96b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4871', 0, 114, '09-mitre-attack', 'retrieved', '2961C4D2CD3A9FB85CFF10A68F2F42EF5129C99464E20586B07E11BFA1F19AA3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
