VALUES ('doc-09-mitre-attack-p0-4875', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-17T15:35:48.668Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "For [Operation Dream Job](https://attack.mitre.org/campaigns/C0022), [Lazarus Group](https://attack.mitre.org/groups/G0032) developed custom tools such as Sumarta, DBLL Dropper, [Torisma](https://attack.mitre.org/software/S0678), and [DRATzarus](https://attack.mitre.org/software/S0694) for their operations.(Citation: ClearSky Lazarus Aug 2020)(Citation: ESET Lazarus Jun 2020)(Citation: McAfee Lazarus Jul 2020)(Citation: McAfee Lazarus Nov 2020)", "external_references": [{"description": "Beek, C. (2020, November 5). Operation North Star: Behind The Scenes. Retrieved December 20, 2021.", "source_name": "McAfee Lazarus Nov 2020", "url": "https://www.mcafee.com/blogs/other-blogs/mcafee-labs/operation-north-star-behind-the-scenes/"}, {"description": "Breitenbacher, D and Osis, K. (2020, June 17). OPERATION IN(TER)CEPTION: Targeted Attacks Against European Aerospace and Military Companies. Retrieved December 20, 2021.", "source_name": "ESET Lazarus Jun 2020", "url": "https://www.welivesecurity.com/wp-content/uploads/2020/06/ESET_Operation_Interception.pdf"}, {"description": "Cashman, M. (2020, July 29). Operation North Star Campaign. Retrieved December 20, 2021.", "source_name": "McAfee Lazarus Jul 2020", "url": "https://www.mcafee.com/blogs/other-blogs/mcafee-labs/operation-north-star-a-job-offer-thats-too-good-to-be-true/?hilite=%27Operation%27%2C%27North%27%2C%27Star%27"}, {"description": "ClearSky Research Team. (2020, August 13). Operation ''Dream Job'' Widespread North Korean Espionage Campaign. Retrieved December 20, 2021.", "source_name": "ClearSky Lazarus Aug 2020", "url": "https://www.clearskysec.com/wp-content/uploads/2020/08/Dream-Job-Campaign.pdf"}], "id": "relationship--d1bd6ce6-eb5f-41a1-b26f-4fe0d83e51ea", "modified": "2026-07-31T21:14:22.885Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--0257b35b-93ef-4a70-80dd-ad5258e6045b", "spec_version": "2.1", "target_ref": "attack-pattern--212306d8-efa4-44c9-8c2d-ed3d2e224aa0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4875', 0, 166, '09-mitre-attack', 'retrieved', '6F7095D0D604F98AC7B2D3EF638929D1A7081A2BEF8DF57A481F25B8398A9098', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
