VALUES ('doc-09-mitre-attack-p0-4878', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-17T15:31:03.659Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "For [Operation Dream Job](https://attack.mitre.org/campaigns/C0022), [Lazarus Group](https://attack.mitre.org/groups/G0032) compromised servers to host their malicious tools.(Citation: ClearSky Lazarus Aug 2020)(Citation: ESET Lazarus Jun 2020)(Citation: McAfee Lazarus Jul 2020)", "external_references": [{"description": "Breitenbacher, D and Osis, K. (2020, June 17). OPERATION IN(TER)CEPTION: Targeted Attacks Against European Aerospace and Military Companies. Retrieved December 20, 2021.", "source_name": "ESET Lazarus Jun 2020", "url": "https://www.welivesecurity.com/wp-content/uploads/2020/06/ESET_Operation_Interception.pdf"}, {"description": "Cashman, M. (2020, July 29). Operation North Star Campaign. Retrieved December 20, 2021.", "source_name": "McAfee Lazarus Jul 2020", "url": "https://www.mcafee.com/blogs/other-blogs/mcafee-labs/operation-north-star-a-job-offer-thats-too-good-to-be-true/?hilite=%27Operation%27%2C%27North%27%2C%27Star%27"}, {"description": "ClearSky Research Team. (2020, August 13). Operation ''Dream Job'' Widespread North Korean Espionage Campaign. Retrieved December 20, 2021.", "source_name": "ClearSky Lazarus Aug 2020", "url": "https://www.clearskysec.com/wp-content/uploads/2020/08/Dream-Job-Campaign.pdf"}], "id": "relationship--f5c80a6c-8bbe-449d-80fb-8c5d7035d25d", "modified": "2026-07-31T21:14:22.925Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--0257b35b-93ef-4a70-80dd-ad5258e6045b", "spec_version": "2.1", "target_ref": "attack-pattern--e196b5c5-8118-4a1c-ab8a-936586ce3db5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-