VALUES ('doc-09-mitre-attack-p0-4881', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-17T15:10:27.047Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Operation Dream Job](https://attack.mitre.org/campaigns/C0022), [Lazarus Group](https://attack.mitre.org/groups/G0032) archived victim''s data into a RAR file.(Citation: ESET Lazarus Jun 2020)", "external_references": [{"description": "Breitenbacher, D and Osis, K. (2020, June 17). OPERATION IN(TER)CEPTION: Targeted Attacks Against European Aerospace and Military Companies. Retrieved December 20, 2021.", "source_name": "ESET Lazarus Jun 2020", "url": "https://www.welivesecurity.com/wp-content/uploads/2020/06/ESET_Operation_Interception.pdf"}], "id": "relationship--fc62ec8c-5015-4f02-b9b6-3964082d101d", "modified": "2026-07-31T21:14:22.952Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--0257b35b-93ef-4a70-80dd-ad5258e6045b", "spec_version": "2.1", "target_ref": "attack-pattern--00f90846-cbd1-4fc5-9233-df5c2bf2a662", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4881', 0, 77, '09-mitre-attack', 'retrieved', 'FC482EC81EE2EF3A2B83F20BCD1468543D08CF14A862F8BBBEF352E7C4921541', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
