VALUES ('doc-09-mitre-attack-p0-4883', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-06-10T19:34:29.488Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[KV Botnet Activity](https://attack.mitre.org/campaigns/C0035) gathers victim IP information during initial installation stages.(Citation: Lumen KVBotnet 2023)", "external_references": [{"description": "Black Lotus Labs. (2023, December 13). Routers Roasting On An Open Firewall: The KV-Botnet Investigation. Retrieved June 10, 2024.", "source_name": "Lumen KVBotnet 2023", "url": "https://blog.lumen.com/routers-roasting-on-an-open-firewall-the-kv-botnet-investigation/"}], "id": "relationship--429bf982-fdf7-4404-9544-2cc7942b5939", "modified": "2026-07-31T18:47:17.826Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--0c259854-4044-4f6c-ac49-118d484b3e3b", "spec_version": "2.1", "target_ref": "attack-pattern--707399d6-ab3e-4963-9315-d9d3818cd6a0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4883', 0, 70, '09-mitre-attack', 'retrieved', '70750DB2521B31D55C1A3D6C1F1CD5EC9AAA6DBF0291551AD5C2E242D9F8E821', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
