VALUES ('doc-09-mitre-attack-p0-4884', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-06-10T19:09:25.151Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Scripts associated with [KV Botnet Activity](https://attack.mitre.org/campaigns/C0035) initial deployment can identify processes related to security tools and other botnet families for follow-on disabling during installation.(Citation: Lumen KVBotnet 2023)", "external_references": [{"description": "Black Lotus Labs. (2023, December 13). Routers Roasting On An Open Firewall: The KV-Botnet Investigation. Retrieved June 10, 2024.", "source_name": "Lumen KVBotnet 2023", "url": "https://blog.lumen.com/routers-roasting-on-an-open-firewall-the-kv-botnet-investigation/"}], "id": "relationship--49333b91-3071-4d7b-8bbd-b32d2e80d05f", "modified": "2026-07-31T18:47:17.892Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--0c259854-4044-4f6c-ac49-118d484b3e3b", "spec_version": "2.1", "target_ref": "attack-pattern--8f4a33ec-8b1f-4b80-a2f6-642b2e479580", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4884', 0, 83, '09-mitre-attack', 'retrieved', '9168E4ABC55B99361E84FBC6E6CF5B2F7BDC26FDC12FB7059DD20AAB39B8E2E7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
