VALUES ('doc-09-mitre-attack-p0-4886', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-10-03T10:15:12.937Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[KV Botnet Activity](https://attack.mitre.org/campaigns/C0035) included the use of scripts to download additional payloads when compromising network nodes.(Citation: Lumen KVBotnet 2023)", "external_references": [{"description": "Black Lotus Labs. (2023, December 13). Routers Roasting On An Open Firewall: The KV-Botnet Investigation. Retrieved June 10, 2024.", "source_name": "Lumen KVBotnet 2023", "url": "https://blog.lumen.com/routers-roasting-on-an-open-firewall-the-kv-botnet-investigation/"}], "id": "relationship--6e33c2e7-90b9-4d1e-9925-74d9cf2b4ef6", "modified": "2026-07-31T18:47:17.987Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--0c259854-4044-4f6c-ac49-118d484b3e3b", "spec_version": "2.1", "target_ref": "attack-pattern--e6919abc-99f9-4c6c-95a5-14761e7b2add", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4886', 0, 75, '09-mitre-attack', 'retrieved', '7D443DD783A85DAC397AB1813FEE104A394B1E145CACDD3455FA208D26B50520', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
