VALUES ('doc-09-mitre-attack-p0-4898', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-06-10T19:43:03.983Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[KV Botnet Activity](https://attack.mitre.org/campaigns/C0035) gathers a list of filenames from the following locations during execution of the final botnet stage: \\/usr\\/sbin\\/ , \\/usr\\/bin\\/ , \\/sbin\\/ , \\/pfrm2.0\\/bin\\/ , \\/usr\\/local\\/bin\\/ .(Citation: Lumen KVBotnet 2023)", "external_references": [{"description": "Black Lotus Labs. (2023, December 13). Routers Roasting On An Open Firewall: The KV-Botnet Investigation. Retrieved June 10, 2024.", "source_name": "Lumen KVBotnet 2023", "url": "https://blog.lumen.com/routers-roasting-on-an-open-firewall-the-kv-botnet-investigation/"}], "id": "relationship--deaf1941-b388-44e5-a8e9-09da85bf1067", "modified": "2026-07-31T18:47:18.521Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--0c259854-4044-4f6c-ac49-118d484b3e3b", "spec_version": "2.1", "target_ref": "attack-pattern--7bc57495-ea59-4380-be31-a64af124ef18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4898', 0, 88, '09-mitre-attack', 'retrieved', '23EE17A660C3320027EBA0DAB1C29B7AD73B83A5319C9D20A8969AB4603DDE06', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
