VALUES ('doc-09-mitre-attack-p0-4900', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-10-03T10:14:24.083Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[KV Botnet Activity](https://attack.mitre.org/campaigns/C0035) involved removal of security tools, as well as other identified IOT malware, from compromised devices.(Citation: Lumen KVBotnet 2023)", "external_references": [{"description": "Black Lotus Labs. (2023, December 13). Routers Roasting On An Open Firewall: The KV-Botnet Investigation. Retrieved June 10, 2024.", "source_name": "Lumen KVBotnet 2023", "url": "https://blog.lumen.com/routers-roasting-on-an-open-firewall-the-kv-botnet-investigation/"}], "id": "relationship--fb94932d-5286-42c4-817d-5d04f59763b2", "modified": "2026-07-31T18:47:18.603Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--0c259854-4044-4f6c-ac49-118d484b3e3b", "spec_version": "2.1", "target_ref": "attack-pattern--cba37adb-d6fb-4610-b069-dd04c0643384", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4900', 0, 77, '09-mitre-attack', 'retrieved', '45649300A13D7859A5797AACA4EE80A7868EF0E6DE935EF58B98E6792CEE2AC6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
