VALUES ('doc-09-mitre-attack-p0-4902', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-06-10T19:46:58.042Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[KV Botnet Activity](https://attack.mitre.org/campaigns/C0035) involves managing events on victim systems via libevent to execute a callback function when any running process contains the following references in their path without also having a reference to bioset : busybox, wget, curl, tftp, telnetd, or lua. If the bioset string is not found, the related process is terminated.(Citation: Lumen KVBotnet 2023)", "external_references": [{"description": "Black Lotus Labs. (2023, December 13). Routers Roasting On An Open Firewall: The KV-Botnet Investigation. Retrieved June 10, 2024.", "source_name": "Lumen KVBotnet 2023", "url": "https://blog.lumen.com/routers-roasting-on-an-open-firewall-the-kv-botnet-investigation/"}], "id": "relationship--bf492c3c-026c-45f3-bdc4-9ea200af2bb4", "modified": "2026-08-04T20:30:56.920Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--0c259854-4044-4f6c-ac49-118d484b3e3b", "spec_version": "2.1", "target_ref": "attack-pattern--b6301b64-ef57-4cce-bb0b-77026f14a8db", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4902', 0, 113, '09-mitre-attack', 'retrieved', '9D749B0A450A4F48E6DF554ED83E7B4B5D4CE5795E2059451FF9F6678DCF4584', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
