VALUES ('doc-09-mitre-attack-p0-4903', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-11-20T23:23:16.653Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [FrostyGoop Incident](https://attack.mitre.org/campaigns/C0041), the adversary retrieved the contents of the Security Account Manager (SAM) hive in the victim environment for credential capture.(Citation: Dragos FROSTYGOOP 2024)", "external_references": [{"description": "Mark Graham, Carolyn Ahlers, Kyle O''Meara; Dragos. (2024, July). Impact of FrostyGoop ICS Malware on Connected OT Systems. Retrieved November 20, 2024.", "source_name": "Dragos FROSTYGOOP 2024", "url": "https://hub.dragos.com/hubfs/Reports/Dragos-FrostyGoop-ICS-Malware-Intel-Brief-0724_r2.pdf"}], "id": "relationship--20295e2e-8cb9-43d2-905d-13a9ecf6cde4", "modified": "2026-07-31T20:48:13.511Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--1169ff24-b35f-4d8d-8cf3-643a2834227f", "spec_version": "2.1", "target_ref": "attack-pattern--1644e709-12d2-41e5-a60f-3470991f5011", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4903', 0, 84, '09-mitre-attack', 'retrieved', 'EB1D0256F64644A5708A89B71887D8D7DD06F3315BDC532FC5BDD98FC6CAD40E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
