VALUES ('doc-09-mitre-attack-p0-4904', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-11-20T23:24:53.469Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [FrostyGoop Incident](https://attack.mitre.org/campaigns/C0041), the adversary initiated Layer Two Tunnelling Protocol (L2TP) connections to Moscow-based IP addresses.(Citation: Dragos FROSTYGOOP 2024)", "external_references": [{"description": "Mark Graham, Carolyn Ahlers, Kyle O''Meara; Dragos. (2024, July). Impact of FrostyGoop ICS Malware on Connected OT Systems. Retrieved November 20, 2024.", "source_name": "Dragos FROSTYGOOP 2024", "url": "https://hub.dragos.com/hubfs/Reports/Dragos-FrostyGoop-ICS-Malware-Intel-Brief-0724_r2.pdf"}], "id": "relationship--36223feb-8e44-47e9-9092-d03abf148107", "modified": "2026-07-31T20:48:13.519Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--1169ff24-b35f-4d8d-8cf3-643a2834227f", "spec_version": "2.1", "target_ref": "attack-pattern--355be19c-ffc9-46d5-8d50-d6a036c675b6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4904', 0, 78, '09-mitre-attack', 'retrieved', '53D251F3E9B301625A7DAB8D095889CEA86EEF800A15A5642FC6C56AEED2E914', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
