VALUES ('doc-09-mitre-attack-p0-4905', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-11-20T23:19:34.026Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FrostyGoop Incident](https://attack.mitre.org/campaigns/C0041) deployed a ReGeorg variant web shell to impacted systems following initial access for persistence.(Citation: Dragos FROSTYGOOP 2024)", "external_references": [{"description": "Mark Graham, Carolyn Ahlers, Kyle O''Meara; Dragos. (2024, July). Impact of FrostyGoop ICS Malware on Connected OT Systems. Retrieved November 20, 2024.", "source_name": "Dragos FROSTYGOOP 2024", "url": "https://hub.dragos.com/hubfs/Reports/Dragos-FrostyGoop-ICS-Malware-Intel-Brief-0724_r2.pdf"}], "id": "relationship--4e7e832c-4066-4045-b180-8585d50adc0c", "modified": "2026-07-31T20:48:13.536Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--1169ff24-b35f-4d8d-8cf3-643a2834227f", "spec_version": "2.1", "target_ref": "attack-pattern--5d0d3609-d06d-49e1-b9c9-b544e0c618cb", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4905', 0, 78, '09-mitre-attack', 'retrieved', '8C4FC15A1F50D066C752163E10D6B02288229E284F707663530A0A96B00F9B5F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
