VALUES ('doc-09-mitre-attack-p0-4906', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-11-20T23:27:17.617Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [FrostyGoop Incident](https://attack.mitre.org/campaigns/C0041), the adversary downgraded firmware on victim devices in order to impair visibility into the process environment.(Citation: Dragos FROSTYGOOP 2024)", "external_references": [{"description": "Mark Graham, Carolyn Ahlers, Kyle O''Meara; Dragos. (2024, July). Impact of FrostyGoop ICS Malware on Connected OT Systems. Retrieved November 20, 2024.", "source_name": "Dragos FROSTYGOOP 2024", "url": "https://hub.dragos.com/hubfs/Reports/Dragos-FrostyGoop-ICS-Malware-Intel-Brief-0724_r2.pdf"}], "id": "relationship--898120ce-0d97-424b-b0a1-70bfc84767ff", "modified": "2026-07-31T20:48:13.544Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--1169ff24-b35f-4d8d-8cf3-643a2834227f", "spec_version": "2.1", "target_ref": "attack-pattern--30904c16-39f9-41c6-b01a-500eb8878442", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4906', 0, 81, '09-mitre-attack', 'retrieved', '53E7BE5AE0D318A2B726F7C3D48191CC3D75A0382B1B22F3554AC4834F204669', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
