VALUES ('doc-09-mitre-attack-p0-4910', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-16T16:47:06.011Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [SharePoint ToolShell Exploitation](https://attack.mitre.org/campaigns/C0058), threat actors executed `whoami` on victim machines to enumerate user context and validate privilege levels.(Citation: Microsoft SharePoint Exploit JUL 2025)(Citation: SentinelOne ToolShell JUL 2025)", "external_references": [{"description": "Kenin, S. et al. (2025, July 21). SharePoint ToolShell | Zero-Day Exploited in-the-Wild Targets Enterprise Servers. Retrieved October 15, 2025.", "source_name": "SentinelOne ToolShell JUL 2025", "url": "https://www.sentinelone.com/blog/sharepoint-toolshell-zero-day-exploited-in-the-wild-targets-enterprise-servers/"}, {"description": "Microsoft Threat Intelligence. (2025, July 22). Disrupting active exploitation of on-premises SharePoint vulnerabilities. Retrieved October 15, 2025.", "source_name": "Microsoft SharePoint Exploit JUL 2025", "url": "https://www.microsoft.com/en-us/security/blog/2025/07/22/disrupting-active-exploitation-of-on-premises-sharepoint-vulnerabilities/#storm-2603"}], "id": "relationship--12e8b4b1-e6b4-4ced-b171-e9e2fb881e7b", "modified": "2026-07-31T18:47:17.937Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--1a0576df-df21-4775-843e-844d8a58a94b", "spec_version": "2.1", "target_ref": "attack-pattern--03d7999c-1f4c-42cc-8373-e7690d318104", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4910', 0, 112, '09-mitre-attack', 'retrieved', 'F72045FAF75831EF21CD78403277CB34B1A0E2C1E94A9325C3BD59FE6295D8DD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved",