VALUES ('doc-09-mitre-attack-p0-4912', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-16T19:04:25.171Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [SharePoint ToolShell Exploitation](https://attack.mitre.org/campaigns/C0058), threat actors UPX-packed malicous payloads including 4L4MD4R ransomware.(Citation: Palo Alto SharePoint Vulnerabilities JUL 2025)", "external_references": [{"description": "Unit 42. (2025, July 31). Active Exploitation of Microsoft SharePoint Vulnerabilities: Threat Brief (Updated). Retrieved October 15, 2025.", "source_name": "Palo Alto SharePoint Vulnerabilities JUL 2025", "url": "https://unit42.paloaltonetworks.com/microsoft-sharepoint-cve-2025-49704-cve-2025-49706-cve-2025-53770/"}], "id": "relationship--33b2a8e7-658a-4c00-bd88-bcc36c980012", "modified": "2026-07-31T18:47:18.022Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--1a0576df-df21-4775-843e-844d8a58a94b", "spec_version": "2.1", "target_ref": "attack-pattern--deb98323-e13f-4b0c-8d94-175379069062", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4912', 0, 76, '09-mitre-attack', 'retrieved', 'CE7BCCBF4C1B41BA77208C02E0975FD31E031E2C525968175738A0CB311CF045', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
