VALUES ('doc-09-mitre-attack-p0-4914', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-16T16:45:38.237Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [SharePoint ToolShell Exploitation](https://attack.mitre.org/campaigns/C0058), threat actors leveraged commands to locate accessible file shares, backup paths, or SharePoint content.(Citation: Microsoft SharePoint Exploit JUL 2025)", "external_references": [{"description": "Microsoft Threat Intelligence. (2025, July 22). Disrupting active exploitation of on-premises SharePoint vulnerabilities. Retrieved October 15, 2025.", "source_name": "Microsoft SharePoint Exploit JUL 2025", "url": "https://www.microsoft.com/en-us/security/blog/2025/07/22/disrupting-active-exploitation-of-on-premises-sharepoint-vulnerabilities/#storm-2603"}], "id": "relationship--355c008f-e48a-45f1-8ab8-f04fff3b7915", "modified": "2026-07-31T18:47:18.102Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--1a0576df-df21-4775-843e-844d8a58a94b", "spec_version": "2.1", "target_ref": "attack-pattern--7bc57495-ea59-4380-be31-a64af124ef18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4914', 0, 79, '09-mitre-attack', 'retrieved', 'D4013302957718E02F3F34FF2473EDEC8C6B158A556583E67787ADD23C6D9E18', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
