VALUES ('doc-09-mitre-attack-p0-4922', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-16T19:33:54.228Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [SharePoint ToolShell Exploitation](https://attack.mitre.org/campaigns/C0058), threat actors demanded ransom payments to unencrypt filesystems and to refrain from publishing sensitive data exfiltrated from victim networks.(Citation: Palo Alto SharePoint Vulnerabilities JUL 2025)", "external_references": [{"description": "Unit 42. (2025, July 31). Active Exploitation of Microsoft SharePoint Vulnerabilities: Threat Brief (Updated). Retrieved October 15, 2025.", "source_name": "Palo Alto SharePoint Vulnerabilities JUL 2025", "url": "https://unit42.paloaltonetworks.com/microsoft-sharepoint-cve-2025-49704-cve-2025-49706-cve-2025-53770/"}], "id": "relationship--6948916f-eba5-4f23-8630-22035d00b7c3", "modified": "2026-07-31T18:47:18.372Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--1a0576df-df21-4775-843e-844d8a58a94b", "spec_version": "2.1", "target_ref": "attack-pattern--851e071f-208d-4c79-adc6-5974c85c78f3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4922', 0, 87, '09-mitre-attack', 'retrieved', 'B75D9FF1C3E03D9B7570562020BB06916F99B0163D24C3A11E1CF6C4BEED5B23', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
