VALUES ('doc-09-mitre-attack-p0-4938', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-15T20:46:16.581Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [SharePoint ToolShell Exploitation](https://attack.mitre.org/campaigns/C0058), threat actors leveraged tools including [Impacket](https://attack.mitre.org/software/S0357), [PsExec](https://attack.mitre.org/software/S0029), and [Mimikatz](https://attack.mitre.org/software/S0002).(Citation: Microsoft SharePoint Exploit JUL 2025)\n", "external_references": [{"description": "Microsoft Threat Intelligence. (2025, July 22). Disrupting active exploitation of on-premises SharePoint vulnerabilities. Retrieved October 15, 2025.", "source_name": "Microsoft SharePoint Exploit JUL 2025", "url": "https://www.microsoft.com/en-us/security/blog/2025/07/22/disrupting-active-exploitation-of-on-premises-sharepoint-vulnerabilities/#storm-2603"}], "id": "relationship--d3bc0783-3912-40b4-a995-4241ef218977", "modified": "2026-07-31T18:47:19.095Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--1a0576df-df21-4775-843e-844d8a58a94b", "spec_version": "2.1", "target_ref": "attack-pattern--a2fdce72-04b2-409a-ac10-cc1695f4fce0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4938', 0, 74, '09-mitre-attack', 'retrieved', '00F9C52CB3065A2BA83C085BAAE37A1EF6461D8FF2DCA8AE83511B2E539A582F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
