VALUES ('doc-09-mitre-attack-p0-4964', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-07T19:55:59.299Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Frankenstein](https://attack.mitre.org/campaigns/C0001), the threat actors used WMI queries to check if various security applications were running as well as to determine the operating system version.(Citation: Talos Frankenstein June 2019)", "external_references": [{"description": "Adamitis, D. et al. (2019, June 4). It''s alive: Threat actors cobble together open-source pieces into monstrous Frankenstein campaign. Retrieved May 11, 2020.", "source_name": "Talos Frankenstein June 2019", "url": "https://blog.talosintelligence.com/2019/06/frankenstein-campaign.html"}], "id": "relationship--9ef2a5a7-3be8-426a-8411-ca78e35cef3a", "modified": "2026-07-31T18:47:19.279Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--26d9ebae-de59-427f-ae9a-349456bae4b1", "spec_version": "2.1", "target_ref": "attack-pattern--01a5a209-b94c-450b-b7f9-946497d91055", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4964', 0, 90, '09-mitre-attack', 'retrieved', '932B251B813821318E78633BD9113FEE30850EACC0D5957CF1A21100123F1FEC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
