VALUES ('doc-09-mitre-attack-p0-4965', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-07T13:48:41.424Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Frankenstein](https://attack.mitre.org/campaigns/C0001), the threat actors used [Empire](https://attack.mitre.org/software/S0363) to automatically gather the username, domain name, machine name, and other system information.(Citation: Talos Frankenstein June 2019)", "external_references": [{"description": "Adamitis, D. et al. (2019, June 4). It''s alive: Threat actors cobble together open-source pieces into monstrous Frankenstein campaign. Retrieved May 11, 2020.", "source_name": "Talos Frankenstein June 2019", "url": "https://blog.talosintelligence.com/2019/06/frankenstein-campaign.html"}], "id": "relationship--ab431fe4-eb1b-48ed-a105-7d50b8d0beda", "modified": "2026-07-31T18:47:19.326Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--26d9ebae-de59-427f-ae9a-349456bae4b1", "spec_version": "2.1", "target_ref": "attack-pattern--30208d3e-0d6b-43c8-883e-44462a514619", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4965', 0, 85, '09-mitre-attack', 'retrieved', '5AB8F2170AFD22270B1248785B05A36D94A5B657118239299DF00A4EABA2E016', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
