VALUES ('doc-09-mitre-attack-p0-4968', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-07T14:19:54.989Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Frankenstein](https://attack.mitre.org/campaigns/C0001), the threat actors collected information via [Empire](https://attack.mitre.org/software/S0363), which sent the data back to the adversary''s C2.(Citation: Talos Frankenstein June 2019)", "external_references": [{"description": "Adamitis, D. et al. (2019, June 4). It''s alive: Threat actors cobble together open-source pieces into monstrous Frankenstein campaign. Retrieved May 11, 2020.", "source_name": "Talos Frankenstein June 2019", "url": "https://blog.talosintelligence.com/2019/06/frankenstein-campaign.html"}], "id": "relationship--cbc251b7-5541-408f-b11d-c57d600fc8cf", "modified": "2026-07-31T18:47:19.447Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--26d9ebae-de59-427f-ae9a-349456bae4b1", "spec_version": "2.1", "target_ref": "attack-pattern--92d7da27-2d91-488e-a00c-059dc162766d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4968', 0, 83, '09-mitre-attack', 'retrieved', '4F7014802E55E1D6BB495BDA6BD0D9E18A0D88375B03FB35F24888282EE3337F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
