VALUES ('doc-09-mitre-attack-p0-4970', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-07T14:14:50.343Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Frankenstein](https://attack.mitre.org/campaigns/C0001), the threat actors deobfuscated Base64-encoded commands following the execution of a malicious script, which revealed a small script designed to obtain an additional payload.(Citation: Talos Frankenstein June 2019)", "external_references": [{"description": "Adamitis, D. et al. (2019, June 4). It''s alive: Threat actors cobble together open-source pieces into monstrous Frankenstein campaign. Retrieved May 11, 2020.", "source_name": "Talos Frankenstein June 2019", "url": "https://blog.talosintelligence.com/2019/06/frankenstein-campaign.html"}], "id": "relationship--d87615c7-501a-4b78-87fb-ba2c1a2faffb", "modified": "2026-07-31T18:47:19.501Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--26d9ebae-de59-427f-ae9a-349456bae4b1", "spec_version": "2.1", "target_ref": "attack-pattern--3ccef7ae-cb5e-48f6-8302-897105fbf55c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4970', 0, 91, '09-mitre-attack', 'retrieved', 'BB58BFCF8D30CC8BBF7B4CA15AD5F27872B4332C7FADBCC1121A23DB221C679B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
