VALUES ('doc-09-mitre-attack-p0-4995', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-14T22:49:06.445Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mustang Panda](https://attack.mitre.org/groups/G0129) initial payloads downloaded a Windows Installer MSI file that in turn dropped follow-on files leading to installation of [PlugX](https://attack.mitre.org/software/S0013) during [RedDelta Modified PlugX Infection Chain Operations](https://attack.mitre.org/campaigns/C0047).(Citation: Recorded Future RedDelta 2025)", "external_references": [{"description": "Insikt Group. (2025, January 9). Chinese State-Sponsored RedDelta Targeted Taiwan, Mongolia, and Southeast Asia with Adapted PlugX Infection Chain. Retrieved January 14, 2025.", "source_name": "Recorded Future RedDelta 2025", "url": "https://go.recordedfuture.com/hubfs/reports/cta-cn-2025-0109.pdf"}], "id": "relationship--bfdc1a69-6bc6-4a73-a2f2-48e947d19895", "modified": "2026-07-31T18:47:19.777Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--276671b5-5425-48db-ad65-c8c2564a969b", "spec_version": "2.1", "target_ref": "attack-pattern--365be77f-fc0e-42ee-bac8-4faf806d9336", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4995', 0, 93, '09-mitre-attack', 'retrieved', '4835F23EBEFDE85EA6BEB0AA81E07186E5DB27754AC3F396ACE208181A506182', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
