VALUES ('doc-09-mitre-attack-p0-4996', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-14T22:44:34.469Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mustang Panda](https://attack.mitre.org/groups/G0129) registered adversary-controlled domains during [RedDelta Modified PlugX Infection Chain Operations](https://attack.mitre.org/campaigns/C0047) that were re-registrations of expired domains.(Citation: Recorded Future RedDelta 2025)", "external_references": [{"description": "Insikt Group. (2025, January 9). Chinese State-Sponsored RedDelta Targeted Taiwan, Mongolia, and Southeast Asia with Adapted PlugX Infection Chain. Retrieved January 14, 2025.", "source_name": "Recorded Future RedDelta 2025", "url": "https://go.recordedfuture.com/hubfs/reports/cta-cn-2025-0109.pdf"}], "id": "relationship--df780e2f-1618-4ce0-8a89-6ac073b57cc9", "modified": "2026-07-31T18:47:19.794Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--276671b5-5425-48db-ad65-c8c2564a969b", "spec_version": "2.1", "target_ref": "attack-pattern--40f5caa0-4cb7-4117-89fc-d421bb493df3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4996', 0, 83, '09-mitre-attack', 'retrieved', '88826EE3B5B9B1A74AA087E2AE7CAB674551319A6CD2B76713192C079667DAA0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
