VALUES ('doc-09-mitre-attack-p0-4997', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-14T22:57:05.909Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mustang Panda](https://attack.mitre.org/groups/G0129) used Microsoft Management Console Snap-In Control files, or MSC files, executed via MMC to run follow-on PowerShell commands during [RedDelta Modified PlugX Infection Chain Operations](https://attack.mitre.org/campaigns/C0047).(Citation: Recorded Future RedDelta 2025)", "external_references": [{"description": "Insikt Group. (2025, January 9). Chinese State-Sponsored RedDelta Targeted Taiwan, Mongolia, and Southeast Asia with Adapted PlugX Infection Chain. Retrieved January 14, 2025.", "source_name": "Recorded Future RedDelta 2025", "url": "https://go.recordedfuture.com/hubfs/reports/cta-cn-2025-0109.pdf"}], "id": "relationship--f2443bd0-d421-4710-9375-81f55968729a", "modified": "2026-07-31T18:47:19.855Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--276671b5-5425-48db-ad65-c8c2564a969b", "spec_version": "2.1", "target_ref": "attack-pattern--ffbcfdb0-de22-4106-9ed3-fc23c8a01407", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4997', 0, 92, '09-mitre-attack', 'retrieved', 'B40E60A03005659141C34CC07275BDC2469B3B10299DB0358BC8F14B42EEC690', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
