VALUES ('doc-09-mitre-attack-p0-4999', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-14T22:39:16.726Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RedDelta Modified PlugX Infection Chain Operations](https://attack.mitre.org/campaigns/C0047) was an campaign linked to [Mustang Panda](https://attack.mitre.org/groups/G0129) operations.(Citation: Recorded Future RedDelta 2025)", "external_references": [{"description": "Insikt Group. (2025, January 9). Chinese State-Sponsored RedDelta Targeted Taiwan, Mongolia, and Southeast Asia with Adapted PlugX Infection Chain. Retrieved January 14, 2025.", "source_name": "Recorded Future RedDelta 2025", "url": "https://go.recordedfuture.com/hubfs/reports/cta-cn-2025-0109.pdf"}], "id": "relationship--88015217-a3df-4654-bea1-b1d8241b67ee", "modified": "2026-07-31T18:47:52.750Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "attributed-to", "revoked": false, "source_ref": "campaign--276671b5-5425-48db-ad65-c8c2564a969b", "spec_version": "2.1", "target_ref": "intrusion-set--420ac20b-f2b9-42b8-aa1a-6d4b72895ca4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-4999', 0, 79, '09-mitre-attack', 'retrieved', '1328346E462AF1E595D2C5EB86F9B21CD33EB807B85A97DC43C8C036D5C2D974', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
