VALUES ('doc-09-mitre-attack-p0-5007', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-06-30T18:19:32.277Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [RedPenguin](https://attack.mitre.org/campaigns/C0056), [UNC3886](https://attack.mitre.org/groups/G1048) used an implant to delete logs associated with unauthorized access to targeted Junos OS devices.(Citation: Juniper RedPenguin MAR 2025)", "external_references": [{"description": "Juniper Networks, Cybersecurity R&D. (2025, March 11). The RedPenguin Malware Incident. Retrieved June 24, 2025.", "source_name": "Juniper RedPenguin MAR 2025", "url": "https://supportportal.juniper.net/sfc/servlet.shepherd/document/download/069Dp00000FzdmIIAR?operationContext=S1"}], "id": "relationship--6b8bded7-ea8c-45e4-8888-1ed2a6d1e134", "modified": "2026-07-31T18:47:20.056Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--35879bf3-0a21-4cc1-9e42-6de917a22501", "spec_version": "2.1", "target_ref": "attack-pattern--3975dbb5-0e1e-4f5b-bae1-cf2ab84b46dc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5007', 0, 75, '09-mitre-attack', 'retrieved', '8997AA6A14C8FBE7EFBA6203FBA575B940AB63DB3A98744EBED39890FA34DA3E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
