VALUES ('doc-09-mitre-attack-p0-5023', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-06-26T18:59:34.031Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [RedPenguin](https://attack.mitre.org/campaigns/C0056), [UNC3886](https://attack.mitre.org/groups/G1048) leveraged malware that used UDP and TCP sockets for C2.(Citation: Mandiant UNC3886 Juniper Routers MAR 2025)(Citation: Censys RedPenguin MAR 2025)(Citation: Juniper RedPenguin MAR 2025)", "external_references": [{"description": "Censys Research Team. (2025, March 14). JunOS and RedPenguin. Retrieved June 24, 2025.", "source_name": "Censys RedPenguin MAR 2025", "url": "https://censys.com/blog/junos-and-redpenguin"}, {"description": "Juniper Networks, Cybersecurity R&D. (2025, March 11). The RedPenguin Malware Incident. Retrieved June 24, 2025.", "source_name": "Juniper RedPenguin MAR 2025", "url": "https://supportportal.juniper.net/sfc/servlet.shepherd/document/download/069Dp00000FzdmIIAR?operationContext=S1"}, {"description": "Lamparski, L. et al. (2025, March 11). Ghost in the Router: China-Nexus Espionage Actor UNC3886 Targets Juniper Routers. Retrieved June 24, 2025.", "source_name": "Mandiant UNC3886 Juniper Routers MAR 2025", "url": "https://cloud.google.com/blog/topics/threat-intelligence/china-nexus-espionage-targets-juniper-routers"}], "id": "relationship--e506c970-b916-4107-9f52-133b2e1b4e6f", "modified": "2026-07-31T18:47:20.412Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--35879bf3-0a21-4cc1-9e42-6de917a22501", "spec_version": "2.1", "target_ref": "attack-pattern--c21d5a77-d422-4a69-acd7-2c53c1faa34b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5023', 0, 133, '09-mitre-attack'