VALUES ('doc-09-mitre-attack-p0-5028', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-06-30T19:58:04.555Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "In mid-2024 Mandiant identified custom TINYSHELL-based backdoors deployed on Juniper Networks’ Junos OS routers. Mandiant attributed these backdoors to the China-nexus espionage group [UNC3886](https://attack.mitre.org/groups/G1048).(Citation: Mandiant UNC3886 Juniper Routers MAR 2025)", "external_references": [{"description": "Lamparski, L. et al. (2025, March 11). Ghost in the Router: China-Nexus Espionage Actor UNC3886 Targets Juniper Routers. Retrieved June 24, 2025.", "source_name": "Mandiant UNC3886 Juniper Routers MAR 2025", "url": "https://cloud.google.com/blog/topics/threat-intelligence/china-nexus-espionage-targets-juniper-routers"}], "id": "relationship--3cde6cab-a70e-45d3-b1e5-a7a6ba08241e", "modified": "2026-07-31T18:47:53.523Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "attributed-to", "revoked": false, "source_ref": "campaign--35879bf3-0a21-4cc1-9e42-6de917a22501", "spec_version": "2.1", "target_ref": "intrusion-set--461b8e25-8f4a-4ea2-a4a8-e39df7ce6630", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5028', 0, 92, '09-mitre-attack', 'retrieved', '8D3EDB12FE9809B86CAE5B0C5BA882AB86E22656F9116872FCF5347EF3C6757D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
