VALUES ('doc-09-mitre-attack-p0-5031', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-26T22:05:55.494Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "For [Operation Sharpshooter](https://attack.mitre.org/campaigns/C0013), the threat actors staged malicious files on Dropbox and other websites.(Citation: McAfee Sharpshooter December 2018)", "external_references": [{"description": "Sherstobitoff, R., Malhotra, A., et. al.. (2018, December 18). Operation Sharpshooter Campaign Targets Global Defense, Critical Infrastructure. Retrieved May 14, 2020.", "source_name": "McAfee Sharpshooter December 2018", "url": "https://www.mcafee.com/enterprise/en-us/assets/reports/rp-operation-sharpshooter.pdf"}], "id": "relationship--68f0beb9-ce3e-44ae-af4d-516c22aa3cf4", "modified": "2026-07-31T18:47:20.180Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--37764c78-2a99-46d1-a7ea-6454b9bf93a0", "spec_version": "2.1", "target_ref": "attack-pattern--3ee16395-03f0-4690-a32e-69ce9ada0f9e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5031', 0, 77, '09-mitre-attack', 'retrieved', '0ECC2AF8D51FDE677B385172E39101D8525772DFA1988197919CBF2D9C3A61A9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
