VALUES ('doc-09-mitre-attack-p0-5034', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-10-13T15:30:51.342Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Operation Sharpshooter](https://attack.mitre.org/campaigns/C0013), threat actors leveraged embedded shellcode to inject a downloader into the memory of Word.(Citation: Threatpost New Op Sharpshooter Data March 2019) ", "external_references": [{"description": "L. O''Donnell. (2019, March 3). RSAC 2019: New Operation Sharpshooter Data Reveals Higher Complexity, Scope. Retrieved September 26, 2022.", "source_name": "Threatpost New Op Sharpshooter Data March 2019", "url": "https://threatpost.com/sharpshooter-complexity-scope/142359/"}], "id": "relationship--9e784751-c08e-43d8-957a-7d9a35e1cf05", "modified": "2026-07-31T18:47:20.236Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--37764c78-2a99-46d1-a7ea-6454b9bf93a0", "spec_version": "2.1", "target_ref": "attack-pattern--43e7dc91-05b2-474c-b9ac-2ed4fe101f4d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5034', 0, 85, '09-mitre-attack', 'retrieved', '41A733FCE5FCFA990DFFD0165F71E109BE32D52C4C955C1D9448529DB7D356E5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
