VALUES ('doc-09-mitre-attack-p0-5035', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-26T21:41:08.513Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Operation Sharpshooter](https://attack.mitre.org/campaigns/C0013), the threat actors used a VBA macro to execute a simple downloader that installed [Rising Sun](https://attack.mitre.org/software/S0448).(Citation: McAfee Sharpshooter December 2018)", "external_references": [{"description": "Sherstobitoff, R., Malhotra, A., et. al.. (2018, December 18). Operation Sharpshooter Campaign Targets Global Defense, Critical Infrastructure. Retrieved May 14, 2020.", "source_name": "McAfee Sharpshooter December 2018", "url": "https://www.mcafee.com/enterprise/en-us/assets/reports/rp-operation-sharpshooter.pdf"}], "id": "relationship--ada86d8c-2c88-442d-8f7a-d9e53937a3f2", "modified": "2026-07-31T18:47:20.262Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--37764c78-2a99-46d1-a7ea-6454b9bf93a0", "spec_version": "2.1", "target_ref": "attack-pattern--dfd7cc1d-e1d8-4394-a198-97c4cab8aa67", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5035', 0, 82, '09-mitre-attack', 'retrieved', 'CEBA6371462A0B72286D41C5EA681BF8524C20A8E725313B6355A9D9257098BB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
