VALUES ('doc-09-mitre-attack-p0-5036', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-26T21:23:16.796Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the investigation of [Operation Sharpshooter](https://attack.mitre.org/campaigns/C0013), security researchers identified [Rising Sun](https://attack.mitre.org/software/S0448) in 87 organizations across the globe and subsequently discovered three variants.(Citation: McAfee Sharpshooter December 2018)(Citation: Bleeping Computer Op Sharpshooter March 2019)", "external_references": [{"description": "I. Ilascu. (2019, March 3). Op ''Sharpshooter'' Connected to North Korea''s Lazarus Group. Retrieved September 26, 2022.", "source_name": "Bleeping Computer Op Sharpshooter March 2019", "url": "https://www.bleepingcomputer.com/news/security/op-sharpshooter-connected-to-north-koreas-lazarus-group/"}, {"description": "Sherstobitoff, R., Malhotra, A., et. al.. (2018, December 18). Operation Sharpshooter Campaign Targets Global Defense, Critical Infrastructure. Retrieved May 14, 2020.", "source_name": "McAfee Sharpshooter December 2018", "url": "https://www.mcafee.com/enterprise/en-us/assets/reports/rp-operation-sharpshooter.pdf"}], "id": "relationship--b4d9d40b-db4f-4e1d-a1ed-a1eb38ebe831", "modified": "2026-07-31T18:47:20.287Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--37764c78-2a99-46d1-a7ea-6454b9bf93a0", "spec_version": "2.1", "target_ref": "malware--56e6b6c2-e573-4969-8bab-783205cebbbf", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5036', 0, 118, '09-mitre-attack', 'retrieved', '29D24D43CFA879C6AA7CB6986AE02DC5B422F607B7D625F0A6C82E722A440CEF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
