VALUES ('doc-09-mitre-attack-p0-5037', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-26T21:38:26.418Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Operation Sharpshooter](https://attack.mitre.org/campaigns/C0013), a first-stage downloader installed [Rising Sun](https://attack.mitre.org/software/S0448) to `%Startup%\\mssync.exe` on a compromised host.(Citation: McAfee Sharpshooter December 2018) ", "external_references": [{"description": "Sherstobitoff, R., Malhotra, A., et. al.. (2018, December 18). Operation Sharpshooter Campaign Targets Global Defense, Critical Infrastructure. Retrieved May 14, 2020.", "source_name": "McAfee Sharpshooter December 2018", "url": "https://www.mcafee.com/enterprise/en-us/assets/reports/rp-operation-sharpshooter.pdf"}], "id": "relationship--b5baa306-e027-4000-9338-0d9df55c5040", "modified": "2026-07-31T18:47:20.320Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--37764c78-2a99-46d1-a7ea-6454b9bf93a0", "spec_version": "2.1", "target_ref": "attack-pattern--9efb1ea7-c37b-4595-9640-b7680cd84279", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5037', 0, 79, '09-mitre-attack', 'retrieved', 'A2357BC651A0091CFFCE397664A8ABDD909C091FA14D6CC058D5CE83F308C0BE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
