VALUES ('doc-09-mitre-attack-p0-5041', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-10-13T15:42:02.324Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Operation Sharpshooter](https://attack.mitre.org/campaigns/C0013), threat actors installed [Rising Sun](https://attack.mitre.org/software/S0448) in the Startup folder and disguised it as `mssync.exe`.(Citation: McAfee Sharpshooter December 2018)", "external_references": [{"description": "Sherstobitoff, R., Malhotra, A., et. al.. (2018, December 18). Operation Sharpshooter Campaign Targets Global Defense, Critical Infrastructure. Retrieved May 14, 2020.", "source_name": "McAfee Sharpshooter December 2018", "url": "https://www.mcafee.com/enterprise/en-us/assets/reports/rp-operation-sharpshooter.pdf"}], "id": "relationship--f9dc35b9-5cf9-4dbf-a1fd-698c95c047c5", "modified": "2026-07-31T18:47:20.410Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--37764c78-2a99-46d1-a7ea-6454b9bf93a0", "spec_version": "2.1", "target_ref": "attack-pattern--1c4e5d32-1fe9-4116-9d9d-59e3925bd6a2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5041', 0, 80, '09-mitre-attack', 'retrieved', 'AEC12A39F0DFC68AA36291F0556AA32A9FB90D40CE623BFA21CF4412E5E2AED5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
