VALUES ('doc-09-mitre-attack-p0-5042', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-26T21:32:44.206Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "For [Operation Sharpshooter](https://attack.mitre.org/campaigns/C0013), the threat actors used the ExpressVPN service to hide their location.(Citation: Bleeping Computer Op Sharpshooter March 2019)", "external_references": [{"description": "I. Ilascu. (2019, March 3). Op ''Sharpshooter'' Connected to North Korea''s Lazarus Group. Retrieved September 26, 2022.", "source_name": "Bleeping Computer Op Sharpshooter March 2019", "url": "https://www.bleepingcomputer.com/news/security/op-sharpshooter-connected-to-north-koreas-lazarus-group/"}], "id": "relationship--fd3fde9b-3e7b-4e74-baff-94dc573c8366", "modified": "2026-07-31T18:47:20.432Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--37764c78-2a99-46d1-a7ea-6454b9bf93a0", "spec_version": "2.1", "target_ref": "attack-pattern--731f4f55-b6d0-41d1-a7a9-072a66389aea", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5042', 0, 77, '09-mitre-attack', 'retrieved', '34D0D4CDF3425E3E241F5C4DBE4DA11EC1A5898B6C01345DE529FAB1A7F585E6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
