VALUES ('doc-09-mitre-attack-p0-5043', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-10-13T20:13:21.262Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Operation Honeybee](https://attack.mitre.org/campaigns/C0006), attackers created email addresses to register for a free account for a control server used for the implants.(Citation: McAfee Honeybee) ", "external_references": [{"description": "Sherstobitoff, R. (2018, March 02). McAfee Uncovers Operation Honeybee, a Malicious Document Campaign Targeting Humanitarian Aid Groups. Retrieved May 16, 2018.", "source_name": "McAfee Honeybee", "url": "https://www.mcafee.com/blogs/other-blogs/mcafee-labs/mcafee-uncovers-operation-honeybee-malicious-document-campaign-targeting-humanitarian-aid-groups/"}], "id": "relationship--02838a73-1e42-4fda-a27b-044d14f303d9", "modified": "2026-07-31T18:47:20.440Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--4553292d-12c6-4a93-934d-12160370d4e0", "spec_version": "2.1", "target_ref": "attack-pattern--65013dd2-bc61-43e3-afb5-a14c4fa7437a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5043', 0, 81, '09-mitre-attack', 'retrieved', 'F129C7C83CB74126F723B7819984885187D2C34529B33EA1566407AE535B1BE2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
