VALUES ('doc-09-mitre-attack-p0-5044', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-16T21:11:01.568Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Operation Honeybee](https://attack.mitre.org/campaigns/C0006) included the use of an upgraded version of [SYSCON](https://attack.mitre.org/software/S0464).(Citation: McAfee Honeybee)", "external_references": [{"description": "Sherstobitoff, R. (2018, March 02). McAfee Uncovers Operation Honeybee, a Malicious Document Campaign Targeting Humanitarian Aid Groups. Retrieved May 16, 2018.", "source_name": "McAfee Honeybee", "url": "https://www.mcafee.com/blogs/other-blogs/mcafee-labs/mcafee-uncovers-operation-honeybee-malicious-document-campaign-targeting-humanitarian-aid-groups/"}], "id": "relationship--0ebf98b6-2cd2-4672-a330-201e9c7a2932", "modified": "2026-07-31T18:47:20.460Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--4553292d-12c6-4a93-934d-12160370d4e0", "spec_version": "2.1", "target_ref": "malware--edf5aee2-9b1c-4252-8e64-25b12f14c8b3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5044', 0, 70, '09-mitre-attack', 'retrieved', 'BE7911A803B13AFE2F1B6FCF5E0E0F72A0B8E01AD11CCF08D75FAC0D95DD3607', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
