VALUES ('doc-09-mitre-attack-p0-5046', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-19T18:28:28.638Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Operation Honeybee](https://attack.mitre.org/campaigns/C0006), the threat actors deployed malware that used API calls, including `CreateProcessAsUser`.(Citation: McAfee Honeybee)", "external_references": [{"description": "Sherstobitoff, R. (2018, March 02). McAfee Uncovers Operation Honeybee, a Malicious Document Campaign Targeting Humanitarian Aid Groups. Retrieved May 16, 2018.", "source_name": "McAfee Honeybee", "url": "https://www.mcafee.com/blogs/other-blogs/mcafee-labs/mcafee-uncovers-operation-honeybee-malicious-document-campaign-targeting-humanitarian-aid-groups/"}], "id": "relationship--28427b29-2088-44f7-8acd-5df104dcb8ee", "modified": "2026-07-31T18:47:20.527Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--4553292d-12c6-4a93-934d-12160370d4e0", "spec_version": "2.1", "target_ref": "attack-pattern--391d824f-0ef1-47a0-b0ee-c59a75e27670", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5046', 0, 73, '09-mitre-attack', 'retrieved', '758AFE0FBB137B3F54657656CD6FEB573DFDAD293FB8C5D944442AF11B1E3805', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
