VALUES ('doc-09-mitre-attack-p0-5059', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-16T22:04:21.925Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Operation Honeybee](https://attack.mitre.org/campaigns/C0006), the threat actors used a batch file that modified the COMSysApp service to load a malicious ipnet.dll payload and to load a DLL into the `svchost.exe` process.(Citation: McAfee Honeybee)", "external_references": [{"description": "Sherstobitoff, R. (2018, March 02). McAfee Uncovers Operation Honeybee, a Malicious Document Campaign Targeting Humanitarian Aid Groups. Retrieved May 16, 2018.", "source_name": "McAfee Honeybee", "url": "https://www.mcafee.com/blogs/other-blogs/mcafee-labs/mcafee-uncovers-operation-honeybee-malicious-document-campaign-targeting-humanitarian-aid-groups/"}], "id": "relationship--981648bc-e5b1-46b3-adf6-92caae84cfa4", "modified": "2026-07-31T18:47:20.853Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--4553292d-12c6-4a93-934d-12160370d4e0", "spec_version": "2.1", "target_ref": "attack-pattern--17cc750b-e95b-4d7d-9dde-49e0de24148c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5059', 0, 89, '09-mitre-attack', 'retrieved', 'C38FE97038B2BD4F207135AC61FDAD10669A4392FCC6CF86E5664E8F24DE9E91', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
