VALUES ('doc-09-mitre-attack-p0-5099', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-28T14:28:29.965Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "In the [Triton Safety Instrumented System Attack](https://attack.mitre.org/campaigns/C0030), [TEMP.Veles](https://attack.mitre.org/groups/G0088) developed, prior to the attack, malware capabilities that would require access to specific and specialized hardware and software.(Citation: FireEye TRITON Dec 2017)", "external_references": [{"description": "Blake Johnson, Dan Caban, Marina Krotofil, Dan Scali, Nathan Brubaker, Christopher Glyer. (2017, December 14). Attackers Deploy New ICS Attack Framework “TRITON” and Cause Operational Disruption to Critical Infrastructure. Retrieved January 12, 2018.", "source_name": "FireEye TRITON Dec 2017", "url": "https://www.fireeye.com/blog/threat-research/2017/12/attackers-deploy-new-ics-attack-framework-triton.html"}], "id": "relationship--97ca11ce-025d-4e46-93d7-deadd4bcd780", "modified": "2026-07-31T20:48:14.223Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--45a98f02-852f-49b2-94c0-c63207bebbbf", "spec_version": "2.1", "target_ref": "attack-pattern--212306d8-efa4-44c9-8c2d-ed3d2e224aa0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5099', 0, 101, '09-mitre-attack', 'retrieved', 'FAF19AB382B273844F25D9A514A0901954AF9523069749B37BE4ABA6589B313B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
