VALUES ('doc-09-mitre-attack-p0-5100', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-28T14:33:21.562Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "In the [Triton Safety Instrumented System Attack](https://attack.mitre.org/campaigns/C0030), [TEMP.Veles](https://attack.mitre.org/groups/G0088) captured credentials as they were being changed by redirecting text-based login codes to websites they controlled.(Citation: Triton-EENews-2017)", "external_references": [{"description": "Blake Sobczak. (2019, March 7). The inside story of the world’s most dangerous malware. Retrieved March 25, 2024.", "source_name": "Triton-EENews-2017", "url": "https://www.eenews.net/articles/the-inside-story-of-the-worlds-most-dangerous-malware/"}], "id": "relationship--aca39122-03de-4eb0-b73a-cbcbc52ca3de", "modified": "2026-07-31T20:48:14.232Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--45a98f02-852f-49b2-94c0-c63207bebbbf", "spec_version": "2.1", "target_ref": "attack-pattern--69e5226d-05dc-4f15-95d7-44f5ed78d06e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5100', 0, 78, '09-mitre-attack', 'retrieved', 'F1FBD7E85143029574CEFF7C8B3F8CB01D6C26B6B63AB3E4D4BCEB3448596E4B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
