VALUES ('doc-09-mitre-attack-p0-5101', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-28T14:24:01.697Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "In the [Triton Safety Instrumented System Attack](https://attack.mitre.org/campaigns/C0030), [TEMP.Veles](https://attack.mitre.org/groups/G0088) used a publicly available PowerShell-based tool, WMImplant.(Citation: FireEye TEMP.Veles 2018)", "external_references": [{"description": "FireEye Intelligence . (2018, October 23). TRITON Attribution: Russian Government-Owned Lab Most Likely Built Custom Intrusion Tools for TRITON Attackers. Retrieved April 16, 2019.", "source_name": "FireEye TEMP.Veles 2018", "url": "https://web.archive.org/web/20190202205824/https://www.fireeye.com/blog/threat-research/2018/10/triton-attribution-russian-government-owned-lab-most-likely-built-tools.html"}], "id": "relationship--b4c5b1ac-a2bd-4440-82bd-2de419ee1517", "modified": "2026-07-31T20:48:14.258Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--45a98f02-852f-49b2-94c0-c63207bebbbf", "spec_version": "2.1", "target_ref": "attack-pattern--970a3432-3237-47ad-bcca-7d8cbb217736", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5101', 0, 79, '09-mitre-attack', 'retrieved', '469B33C3BEAD2E7B6E385F27552DD44EF1283E047B89F78CC284FC5243BD29CD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
