VALUES ('doc-09-mitre-attack-p0-5116', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-30T19:17:35.147Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Operation Dust Storm](https://attack.mitre.org/campaigns/C0016), the threat actors used a watering hole attack on a popular software reseller to exploit the then-zero-day Internet Explorer vulnerability CVE-2014-0322.(Citation: Cylance Dust Storm)", "external_references": [{"description": "Gross, J. (2016, February 23). Operation Dust Storm. Retrieved December 22, 2021.", "source_name": "Cylance Dust Storm", "url": "https://s7d2.scene7.com/is/content/cylance/prod/cylance-web/en-us/resources/knowledge-center/resource-library/reports/Op_Dust_Storm_Report.pdf"}], "id": "relationship--820a35e0-11fe-42c4-84d2-a29cc5026426", "modified": "2026-07-31T20:48:14.703Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--4603cf2f-06d0-4970-9c5d-5071b08c817f", "spec_version": "2.1", "target_ref": "attack-pattern--d742a578-d70e-4d0e-96a6-02a9c30204e6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5116', 0, 77, '09-mitre-attack', 'retrieved', '5F7419D8A6F0E0425669D82A851CCBC5C5E4BECE93583D78295757B36AD36F93', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
