VALUES ('doc-09-mitre-attack-p0-5133', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-27T13:17:12.592Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "(Citation: Andy Greenberg June 2017) (Citation: US District Court Indictment GRU Unit 74455 October 2020)", "external_references": [{"description": "Andy Greenberg. (2017, June 28). How an Entire Nation Became Russia''s Test Lab for Cyberwar. Retrieved September 27, 2023.", "source_name": "Andy Greenberg June 2017", "url": "https://www.wired.com/story/russian-hackers-attack-ukraine/"}, {"description": "Scott W. Brady. (2020, October 15). United States vs. Yuriy Sergeyevich Andrienko et al.. Retrieved November 25, 2020.", "source_name": "US District Court Indictment GRU Unit 74455 October 2020", "url": "https://www.justice.gov/opa/press-release/file/1328521/download"}], "id": "relationship--4d407dda-944a-4974-b1c2-0a04d2c9ee4c", "modified": "2026-08-04T20:48:44.810Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "attributed-to", "revoked": false, "source_ref": "campaign--46421788-b6e1-4256-b351-f8beffd1afba", "spec_version": "2.1", "target_ref": "intrusion-set--381fcf73-60f6-4ab2-9991-6af3cbc35192", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5133', 0, 103, '09-mitre-attack', 'retrieved', 'D62564F64C891296396EDAE55FFD400AE3CE618340FC40C4DF9B0EAE174EC9FF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
