INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-5135', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-27T14:44:57.449Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [2015 Ukraine Electric Power Attack](https://attack.mitre.org/campaigns/C0028), [Sandworm Team](https://attack.mitre.org/groups/G0034) remotely discovered systems over LAN connections. OT systems were visible from the IT network as well, giving adversaries the ability to discover operational assets. (Citation: Charles McLellan March 2016)", "external_references": [{"description": "Charles McLellan. (2016, March 4). How hackers attacked Ukraine''s power grid: Implications for Industrial IoT security. Retrieved September 27, 2023.", "source_name": "Charles McLellan March 2016", "url": "https://www.zdnet.com/article/how-hackers-attacked-ukraines-power-grid-implications-for-industrial-iot-security/"}], "id": "relationship--61ce754c-da32-4f0d-9c5f-bdf4debf7377", "modified": "2026-08-04T20:48:44.861Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--46421788-b6e1-4256-b351-f8beffd1afba", "spec_version": "2.1", "target_ref": "attack-pattern--e358d692-23c0-4a31-9eb6-ecc13a8d7735", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5135', 0, 96, '09-mitre-attack', 'retrieved', 'BF01BDBAD5E1DDB77891E0CDDDCDB84F7B4BB7AC5B9B3692B3CBC0EE2A06FF3F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
