INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-5140', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-27T14:29:27.866Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [2015 Ukraine Electric Power Attack](https://attack.mitre.org/campaigns/C0028), [Sandworm Team](https://attack.mitre.org/groups/G0034) used [BlackEnergy](https://attack.mitre.org/software/S0089)’s network sniffer module to discover user credentials being sent over the network between the local LAN and the power grid’s industrial control systems. (Citation: Charles McLellan March 2016)", "external_references": [{"description": "Charles McLellan. (2016, March 4). How hackers attacked Ukraine''s power grid: Implications for Industrial IoT security. Retrieved September 27, 2023.", "source_name": "Charles McLellan March 2016", "url": "https://www.zdnet.com/article/how-hackers-attacked-ukraines-power-grid-implications-for-industrial-iot-security/"}], "id": "relationship--899c49f0-4a1b-44d8-81e6-fd927a252bd6", "modified": "2026-08-04T20:48:44.964Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--46421788-b6e1-4256-b351-f8beffd1afba", "spec_version": "2.1", "target_ref": "attack-pattern--3257eb21-f9a7-4430-8de1-d8b6e288f529", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5140', 0, 97, '09-mitre-attack', 'retrieved', 'F8C6217C008545FB6A9AF4F9A583BBE56DD6C4A1665E4C2D562851082EE983D8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
