VALUES ('doc-09-mitre-attack-p0-5141', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-27T14:37:57.879Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [2015 Ukraine Electric Power Attack](https://attack.mitre.org/campaigns/C0028), [Sandworm Team](https://attack.mitre.org/groups/G0034) created privileged domain accounts to be used for further exploitation and lateral movement. (Citation: Booz Allen Hamilton)", "external_references": [{"description": "Booz Allen Hamilton. (2016). When The Lights Went Out. Retrieved December 18, 2024.", "source_name": "Booz Allen Hamilton", "url": "https://www.boozallen.com/content/dam/boozallen/documents/2016/09/ukraine-report-when-the-lights-went-out.pdf"}], "id": "relationship--8a14f269-467e-49f8-a53f-ba1ad7fe5731", "modified": "2026-08-04T20:48:44.976Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--46421788-b6e1-4256-b351-f8beffd1afba", "spec_version": "2.1", "target_ref": "attack-pattern--7610cada-1499-41a4-b3dd-46467b68d177", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5141', 0, 76, '09-mitre-attack', 'retrieved', '8B7C29846EF3CCDC1B55E89A2A3A6E0237536C48D3CC2ADF855449B6003730C7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
