INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-5142', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-27T14:45:52.796Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [2015 Ukraine Electric Power Attack](https://attack.mitre.org/campaigns/C0028), [Sandworm Team](https://attack.mitre.org/groups/G0034) used a backdoor which could execute a supplied DLL using `rundll32.exe`. (Citation: Booz Allen Hamilton)", "external_references": [{"description": "Booz Allen Hamilton. (2016). When The Lights Went Out. Retrieved December 18, 2024.", "source_name": "Booz Allen Hamilton", "url": "https://www.boozallen.com/content/dam/boozallen/documents/2016/09/ukraine-report-when-the-lights-went-out.pdf"}], "id": "relationship--a2d91513-68d5-4df2-ab2f-05a25b72f419", "modified": "2026-08-04T20:48:45.045Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--46421788-b6e1-4256-b351-f8beffd1afba", "spec_version": "2.1", "target_ref": "attack-pattern--045d0922-2310-4e60-b5e4-3302302cb3c5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5142', 0, 74, '09-mitre-attack', 'retrieved', 'E9439EE9E83EA67A836123352CFB778317AC1C851A5479568E6470FEBB753E08', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
