VALUES ('doc-09-mitre-attack-p0-5154', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-11-21T22:50:53.629Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Indian Critical Infrastructure Intrusions](https://attack.mitre.org/campaigns/C0043), [RedEcho](https://attack.mitre.org/groups/G1042) network activity included SSL traffic over TCP 443 and HTTP traffic over non-standard ports.(Citation: RecordedFuture RedEcho 2021)", "external_references": [{"description": "Recorded Future Insikt Group. (2021, February). China-Linked Group RedEcho Targets the Indian Power Sector Amid Heightened Border Tensions. Retrieved November 21, 2024.", "source_name": "RecordedFuture RedEcho 2021", "url": "https://go.recordedfuture.com/hubfs/reports/cta-2021-0228.pdf"}], "id": "relationship--7a10c6fe-be4a-4229-b038-5de99de13fd6", "modified": "2026-07-31T18:47:22.088Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--4b7f9839-4822-4c19-8a1f-70bb61ba97e1", "spec_version": "2.1", "target_ref": "attack-pattern--df8b2a25-8bdf-4856-953c-a04372b1c161", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5154', 0, 82, '09-mitre-attack', 'retrieved', 'E70C4865109B770F8736C37F1F1C38A4E59B3B02A84FBBE0E618736020FA6240', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
