VALUES ('doc-09-mitre-attack-p0-5156', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-11-21T22:57:58.341Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Indian Critical Infrastructure Intrusions](https://attack.mitre.org/campaigns/C0043) involved the use of [FRP](https://attack.mitre.org/software/S1144) to bridge network boundaries and overcome NAT.(Citation: RecordedFuture RedEcho 2022) [Indian Critical Infrastructure Intrusions](https://attack.mitre.org/campaigns/C0043) also involved the use of VPN tunnels with a potentially compromised MSP entity allowing for direct access to critical infrastructure entity networks.(Citation: Dragos YIR 2021)", "external_references": [{"description": "Dragos. (2022). 2021 ICS Cybersecurity Year in Review. Retrieved November 21, 2024.", "source_name": "Dragos YIR 2021", "url": "https://hub.dragos.com/hubfs/333%20Year%20in%20Review/2021/2021%20ICS%20OT%20Cybersecurity%20Year%20In%20Review%20-%20Dragos%202021.pdf?hsLang=en"}, {"description": "Recorded Future Insikt Group. (2022, April 6). Continued Targeting of Indian Power Grid Assets by Chinese State-Sponsored Activity Group. Retrieved November 21, 2024.", "source_name": "RecordedFuture RedEcho 2022", "url": "https://go.recordedfuture.com/hubfs/reports/ta-2022-0406.pdf"}], "id": "relationship--ae650d07-cc2b-4461-9574-7887f50c833d", "modified": "2026-07-31T18:47:22.143Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--4b7f9839-4822-4c19-8a1f-70bb61ba97e1", "spec_version": "2.1", "target_ref": "attack-pattern--b8017880-4b1e-42de-ad10-ae7ac6705166", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5156', 0, 127, '09-mitre-attack', 'retrieved', '88192DB09C631FA3727B61B4202BD