VALUES ('doc-09-mitre-attack-p0-5158', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-11-21T22:52:03.772Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Indian Critical Infrastructure Intrusions](https://attack.mitre.org/campaigns/C0043), [RedEcho](https://attack.mitre.org/groups/G1042) used non-standard ports such as TCP 8080 for HTTP communication.(Citation: RecordedFuture RedEcho 2021)", "external_references": [{"description": "Recorded Future Insikt Group. (2021, February). China-Linked Group RedEcho Targets the Indian Power Sector Amid Heightened Border Tensions. Retrieved November 21, 2024.", "source_name": "RecordedFuture RedEcho 2021", "url": "https://go.recordedfuture.com/hubfs/reports/cta-2021-0228.pdf"}], "id": "relationship--d00a3ec5-cdbf-4646-a12e-4269dce56774", "modified": "2026-07-31T18:47:22.187Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--4b7f9839-4822-4c19-8a1f-70bb61ba97e1", "spec_version": "2.1", "target_ref": "attack-pattern--b18eae87-b469-4e14-b454-b171b416bc18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5158', 0, 78, '09-mitre-attack', 'retrieved', '76CCD236AE69F6D6FF1AA0912D1E443F201E8770C45D6DEB167BB2BFD9761AE9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
