VALUES ('doc-09-mitre-attack-p0-5165', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-10-13T14:46:34.712Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "For [Operation Spalax](https://attack.mitre.org/campaigns/C0005), the threat actors used Nullsoft Scriptable Install System (NSIS) scripts to install malware.(Citation: ESET Operation Spalax Jan 2021)", "external_references": [{"description": "M. Porolli. (2021, January 21). Operation Spalax: Targeted malware attacks in Colombia. Retrieved September 16, 2022.", "source_name": "ESET Operation Spalax Jan 2021", "url": "https://www.welivesecurity.com/2021/01/12/operation-spalax-targeted-malware-attacks-colombia/"}], "id": "relationship--2b4b6861-7143-4155-aaac-60213a314abd", "modified": "2026-07-31T18:47:22.407Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--4c840263-bbda-440d-a22b-674679ddebf1", "spec_version": "2.1", "target_ref": "attack-pattern--7385dfaf-6886-4229-9ecd-6fd678040830", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5165', 0, 76, '09-mitre-attack', 'retrieved', '4CB7116D42F7C848AA2E8C6E10CD8256C5D2A89651A36DBE2447E1065D158046', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
