VALUES ('doc-09-mitre-attack-p0-5169', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-16T16:03:39.766Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "For [Operation Spalax](https://attack.mitre.org/campaigns/C0005), the threat actors used a variety of packers, including CyaX, to obfuscate malicious executables.(Citation: ESET Operation Spalax Jan 2021)", "external_references": [{"description": "M. Porolli. (2021, January 21). Operation Spalax: Targeted malware attacks in Colombia. Retrieved September 16, 2022.", "source_name": "ESET Operation Spalax Jan 2021", "url": "https://www.welivesecurity.com/2021/01/12/operation-spalax-targeted-malware-attacks-colombia/"}], "id": "relationship--3da56da6-08fe-406b-bd0d-cd4f72dd67f4", "modified": "2026-07-31T18:47:22.517Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--4c840263-bbda-440d-a22b-674679ddebf1", "spec_version": "2.1", "target_ref": "attack-pattern--deb98323-e13f-4b0c-8d94-175379069062", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5169', 0, 77, '09-mitre-attack', 'retrieved', 'F555079C16A92FF07B3B88421FE6E14949B57198EA3D2A250DD4E1AE485F114B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
