VALUES ('doc-09-mitre-attack-p0-5170', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-16T16:00:18.333Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "For [Operation Spalax](https://attack.mitre.org/campaigns/C0005), the threat actors staged malware and malicious files in legitimate hosting services such as OneDrive or MediaFire.(Citation: ESET Operation Spalax Jan 2021)", "external_references": [{"description": "M. Porolli. (2021, January 21). Operation Spalax: Targeted malware attacks in Colombia. Retrieved September 16, 2022.", "source_name": "ESET Operation Spalax Jan 2021", "url": "https://www.welivesecurity.com/2021/01/12/operation-spalax-targeted-malware-attacks-colombia/"}], "id": "relationship--3de46cc5-5049-4105-8fcc-ede3f51f30c5", "modified": "2026-07-31T18:47:22.537Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--4c840263-bbda-440d-a22b-674679ddebf1", "spec_version": "2.1", "target_ref": "attack-pattern--3ee16395-03f0-4690-a32e-69ce9ada0f9e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5170', 0, 80, '09-mitre-attack', 'retrieved', 'EDECFB4D47A08CF98C82C0A2C42B0A967B44B5D79697E2EDFA111D59A143AB0B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
