VALUES ('doc-09-mitre-attack-p0-5173', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-16T15:53:31.177Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Operation Spalax](https://attack.mitre.org/campaigns/C0005), the threat actors sent phishing emails that included a PDF document that in some cases led to the download and execution of malware.(Citation: ESET Operation Spalax Jan 2021)", "external_references": [{"description": "M. Porolli. (2021, January 21). Operation Spalax: Targeted malware attacks in Colombia. Retrieved September 16, 2022.", "source_name": "ESET Operation Spalax Jan 2021", "url": "https://www.welivesecurity.com/2021/01/12/operation-spalax-targeted-malware-attacks-colombia/"}], "id": "relationship--85b4d635-f5f4-4f4f-abc2-31203cad496d", "modified": "2026-07-31T18:47:22.599Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--4c840263-bbda-440d-a22b-674679ddebf1", "spec_version": "2.1", "target_ref": "attack-pattern--2e34237d-8574-43f6-aace-ae2915de8597", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5173', 0, 86, '09-mitre-attack', 'retrieved', 'FC5EE622490886D83728F2919B2330F5CF19E28C6F332E9371315FA1B19B2257', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
