VALUES ('doc-09-mitre-attack-p0-5179', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-10T04:08:45.782Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [3CX Supply Chain Attack](https://attack.mitre.org/campaigns/C0057), [AppleJeus](https://attack.mitre.org/groups/G1049)''s VEILEDSIGNAL creates and listens on a Windows named pipe to exchange messages between modules.(Citation: Mandiant 3cx UNC4736 2023)", "external_references": [{"description": "Jeff Johnson, Fred Plan, Adrian Sanchez, Renato Fontana, Jake Nicastro, Dimiter Andonov, Marius Fodoreanu, Daniel Scott. (2023, April 20). 3CX Software Supply Chain Compromise Initiated by a Prior Software Supply Chain Compromise; Suspected North Korean Actor Responsible. Retrieved August 25, 2025.", "source_name": "Mandiant 3cx UNC4736 2023", "url": "https://cloud.google.com/blog/topics/threat-intelligence/3cx-software-supply-chain-compromise/"}], "id": "relationship--42f40187-5451-4bf4-96e8-d15de1f395c8", "modified": "2026-07-31T18:47:22.288Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--4fd53ccc-c6b1-4e3c-abe8-a456d46d789e", "spec_version": "2.1", "target_ref": "attack-pattern--acd0ba37-7ba9-4cc5-ac61-796586cd856d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5179', 0, 104, '09-mitre-attack', 'retrieved', 'F103035848E79F2C9F2AA63E7DF85722F9CB593671EA13F1AA28CD9C62AE05A5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
