VALUES ('doc-09-mitre-attack-p0-5180', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-22T20:04:57.927Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [3CX Supply Chain Attack](https://attack.mitre.org/campaigns/C0057), [AppleJeus](https://attack.mitre.org/groups/G1049) has gained access to the 3CX corporate environment through legitimate VPN credentials.(Citation: 3cx official statement 2023)", "external_references": [{"description": "Agathocles Prodromou. (2023, April 20). Security Update Thursday 20 April 2023 – Initial Intrusion Vector Found. Retrieved August 25, 2025.", "source_name": "3cx official statement 2023", "url": "https://www.3cx.com/blog/news/mandiant-security-update2/"}], "id": "relationship--4e78a70d-13b0-4539-bc43-0f45417b91c2", "modified": "2026-07-31T18:47:22.324Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--4fd53ccc-c6b1-4e3c-abe8-a456d46d789e", "spec_version": "2.1", "target_ref": "attack-pattern--b17a1a56-e99c-403c-8948-561df0cffe81", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5180', 0, 80, '09-mitre-attack', 'retrieved', '3FAD64E47308F0D2CEDB05E03AD8BBC5570C86E6C2937EBA0EDE769E5A7E9049', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
