VALUES ('doc-09-mitre-attack-p0-5182', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-25T21:33:31.847Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [3CX Supply Chain Attack](https://attack.mitre.org/campaigns/C0057), [AppleJeus](https://attack.mitre.org/groups/G1049) compromised the `www.tradingtechnologies[.]com` website hosting a hidden IFRAME to exploit visitors, two months before the site was known to deliver a compromised version of the X_TRADER software package.(Citation: Mandiant 3cx UNC4736 2023)", "external_references": [{"description": "Jeff Johnson, Fred Plan, Adrian Sanchez, Renato Fontana, Jake Nicastro, Dimiter Andonov, Marius Fodoreanu, Daniel Scott. (2023, April 20). 3CX Software Supply Chain Compromise Initiated by a Prior Software Supply Chain Compromise; Suspected North Korean Actor Responsible. Retrieved August 25, 2025.", "source_name": "Mandiant 3cx UNC4736 2023", "url": "https://cloud.google.com/blog/topics/threat-intelligence/3cx-software-supply-chain-compromise/"}], "id": "relationship--54947050-5539-43fe-a1b4-684900c528d4", "modified": "2026-07-31T18:47:22.408Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--4fd53ccc-c6b1-4e3c-abe8-a456d46d789e", "spec_version": "2.1", "target_ref": "attack-pattern--d742a578-d70e-4d0e-96a6-02a9c30204e6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5182', 0, 118, '09-mitre-attack', 'retrieved', '4AF7FD378613E85E3389A8CAEECB7FE4A449C015E0815395E67453C6CF63E8EB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
