INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-5185', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-20T21:19:27.099Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [3CX Supply Chain Attack](https://attack.mitre.org/campaigns/C0057), [AppleJeus](https://attack.mitre.org/groups/G1049)''s software generates a randomly selected date that is between 1-4 weeks in the future. This timestamp is then checked against the current time of the compromised machine, and the malware will sleep until that time is encountered.(Citation: Unit42 3cx supply chain 2023)", "external_references": [{"description": "Robert Falcone, Josh Grunzweig. (2023, March 30). Threat Brief: 3CXDesktopApp Supply Chain Attack. Retrieved September 15, 2025.", "source_name": "Unit42 3cx supply chain 2023", "url": "https://unit42.paloaltonetworks.com/3cxdesktopapp-supply-chain-attack/"}], "id": "relationship--69e9e6bb-df32-4261-a8fc-4b81fca67990", "modified": "2026-07-31T18:47:22.483Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--4fd53ccc-c6b1-4e3c-abe8-a456d46d789e", "spec_version": "2.1", "target_ref": "attack-pattern--a1df809c-7d0e-459f-8fe5-25474bab770b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5185', 0, 105, '09-mitre-attack', 'retrieved', 'E5CC9DAA264E2E0B8BA6E034822F9A40B8CFC0EB02161D5305CB533F2709626D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
