VALUES ('doc-09-mitre-attack-p0-5187', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-20T21:33:42.680Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [3CX Supply Chain Attack](https://attack.mitre.org/campaigns/C0057), [AppleJeus](https://attack.mitre.org/groups/G1049) leveraged a GitHub repository to host icon files containing the command and control URL.(Citation: Unit42 3cx supply chain 2023)(Citation: Mandiant 3cx UNC4736 2023)", "external_references": [{"description": "Jeff Johnson, Fred Plan, Adrian Sanchez, Renato Fontana, Jake Nicastro, Dimiter Andonov, Marius Fodoreanu, Daniel Scott. (2023, April 20). 3CX Software Supply Chain Compromise Initiated by a Prior Software Supply Chain Compromise; Suspected North Korean Actor Responsible. Retrieved August 25, 2025.", "source_name": "Mandiant 3cx UNC4736 2023", "url": "https://cloud.google.com/blog/topics/threat-intelligence/3cx-software-supply-chain-compromise/"}, {"description": "Robert Falcone, Josh Grunzweig. (2023, March 30). Threat Brief: 3CXDesktopApp Supply Chain Attack. Retrieved September 15, 2025.", "source_name": "Unit42 3cx supply chain 2023", "url": "https://unit42.paloaltonetworks.com/3cxdesktopapp-supply-chain-attack/"}], "id": "relationship--75daf0b5-2ad5-4950-a895-ec7a34de330b", "modified": "2026-07-31T18:47:22.528Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--4fd53ccc-c6b1-4e3c-abe8-a456d46d789e", "spec_version": "2.1", "target_ref": "attack-pattern--f7827069-0bf2-4764-af4f-23fae0d181b7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5187', 0, 135, '09-mitre-attack', 'retrieved', 'D157497E9D072F0A1FF6E1B7E8E71A92E0E141206205B854662BE75EB55B9C40', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
