VALUES ('doc-09-mitre-attack-p0-5197', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-15T17:12:20.198Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [3CX Supply Chain Attack](https://attack.mitre.org/campaigns/C0057), [AppleJeus](https://attack.mitre.org/groups/G1049) added a malicious .dylib file to a .dmg installer package for the macOS 3CX application.(Citation: Unit42 3cx supply chain 2023)", "external_references": [{"description": "Robert Falcone, Josh Grunzweig. (2023, March 30). Threat Brief: 3CXDesktopApp Supply Chain Attack. Retrieved September 15, 2025.", "source_name": "Unit42 3cx supply chain 2023", "url": "https://unit42.paloaltonetworks.com/3cxdesktopapp-supply-chain-attack/"}], "id": "relationship--de58eda3-6389-4648-8965-8e2c096e9686", "modified": "2026-07-31T18:47:22.865Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--4fd53ccc-c6b1-4e3c-abe8-a456d46d789e", "spec_version": "2.1", "target_ref": "attack-pattern--da051493-ae9c-4b1b-9760-c009c46c9b56", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5197', 0, 83, '09-mitre-attack', 'retrieved', '92E6FA8418711DB3297B5146615DDCC315388E99250A5C645CECA14C24E69BDB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
