VALUES ('doc-09-mitre-attack-p0-5199', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-20T21:39:20.086Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [3CX Supply Chain Attack](https://attack.mitre.org/campaigns/C0057), [AppleJeus](https://attack.mitre.org/groups/G1049) leveraged the 3CX application''s electron framework to execute its malicious libraries under the official 3CX electron application.(Citation: Unit42 3cx supply chain 2023)", "external_references": [{"description": "Robert Falcone, Josh Grunzweig. (2023, March 30). Threat Brief: 3CXDesktopApp Supply Chain Attack. Retrieved September 15, 2025.", "source_name": "Unit42 3cx supply chain 2023", "url": "https://unit42.paloaltonetworks.com/3cxdesktopapp-supply-chain-attack/"}], "id": "relationship--eeea8a71-82d7-4f7e-93d2-8c652ebb3c47", "modified": "2026-07-31T18:47:22.909Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--4fd53ccc-c6b1-4e3c-abe8-a456d46d789e", "spec_version": "2.1", "target_ref": "attack-pattern--561ae9aa-c28a-4144-9eec-e7027a14c8c3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5199', 0, 85, '09-mitre-attack', 'retrieved', 'B424CC039AE3037E9F5118597DD5947DBC0D1ACC02B69439A0B28B96A2D5674B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
