VALUES ('doc-09-mitre-attack-p0-5202', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-12T19:48:20.036Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Cutting Edge](https://attack.mitre.org/campaigns/C0029), threat actors used the publicly available Interactsh tool to identify Ivanti Connect Secure VPNs vulnerable to CVE-2024-21893.(Citation: Mandiant Cutting Edge Part 3 February 2024)", "external_references": [{"description": "Lin, M. et al. (2024, February 27). Cutting Edge, Part 3: Investigating Ivanti Connect Secure VPN Exploitation and Persistence Attempts. Retrieved March 1, 2024.", "source_name": "Mandiant Cutting Edge Part 3 February 2024", "url": "https://www.mandiant.com/resources/blog/investigating-ivanti-exploitation-persistence"}], "id": "relationship--1509c545-be16-42be-8ec8-140b13f74555", "modified": "2026-07-31T18:47:22.546Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--4fdd2487-26c1-494e-8702-ec5abe9aa1d9", "spec_version": "2.1", "target_ref": "attack-pattern--5502c4e9-24ef-4d5f-8ee9-9e906c2f82c4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5202', 0, 92, '09-mitre-attack', 'retrieved', '53222C1B3E6512B4EA6B7A124A17655C67503E0ECB510B9450B8264E889EAD12', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
