VALUES ('doc-09-mitre-attack-p0-5208', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-13T20:30:15.028Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Cutting Edge](https://attack.mitre.org/campaigns/C0029), threat actors used malicious SparkGateway plugins to inject shared objects into web process memory on compromised Ivanti Secure Connect VPNs to enable deployment of backdoors.(Citation: Mandiant Cutting Edge Part 3 February 2024)", "external_references": [{"description": "Lin, M. et al. (2024, February 27). Cutting Edge, Part 3: Investigating Ivanti Connect Secure VPN Exploitation and Persistence Attempts. Retrieved March 1, 2024.", "source_name": "Mandiant Cutting Edge Part 3 February 2024", "url": "https://www.mandiant.com/resources/blog/investigating-ivanti-exploitation-persistence"}], "id": "relationship--2f0bcef1-1f30-4585-b158-25d614f5f350", "modified": "2026-07-31T18:47:22.760Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--4fdd2487-26c1-494e-8702-ec5abe9aa1d9", "spec_version": "2.1", "target_ref": "attack-pattern--43e7dc91-05b2-474c-b9ac-2ed4fe101f4d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5208', 0, 100, '09-mitre-attack', 'retrieved', '58821E9C3BDD7E3FA47FA11AC5FF140776E1FB0EBC3684FE50FF07C3C0FE8AB3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
