VALUES ('doc-09-mitre-attack-p0-5227', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-11T20:02:49.292Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Cutting Edge](https://attack.mitre.org/campaigns/C0029), threat actors used Iodine to tunnel IPv4 traffic over DNS.(Citation: Mandiant Cutting Edge Part 2 January 2024)", "external_references": [{"description": "Lin, M. et al. (2024, January 31). Cutting Edge, Part 2: Investigating Ivanti Connect Secure VPN Zero-Day Exploitation. Retrieved February 27, 2024.", "source_name": "Mandiant Cutting Edge Part 2 January 2024", "url": "https://www.mandiant.com/resources/blog/investigating-ivanti-zero-day-exploitation"}], "id": "relationship--9978b502-d1c2-4673-8df5-878f3184fe4e", "modified": "2026-07-31T18:47:23.233Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--4fdd2487-26c1-494e-8702-ec5abe9aa1d9", "spec_version": "2.1", "target_ref": "attack-pattern--4fe28b27-b13c-453e-a386-c2ef362a573b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5227', 0, 83, '09-mitre-attack', 'retrieved', '2A98C86BC8071FB27E9C61447DD618E15886B1C4B4FAC3D3E3B97C5ACA0C4B09', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
