VALUES ('doc-09-mitre-attack-p0-5228', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-01T18:37:30.187Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Cutting Edge](https://attack.mitre.org/campaigns/C0029), threat actors exploited CVE-2023-46805 and CVE-2024-21887 in Ivanti Connect Secure VPN appliances to enable authentication bypass and command injection. A server-side request forgery (SSRF) vulnerability, CVE-2024-21893, was identified later and used to bypass mitigations for the initial two vulnerabilities by chaining with CVE-2024-21887.(Citation: Mandiant Cutting Edge January 2024)(Citation: Volexity Ivanti Zero-Day Exploitation January 2024)(Citation: Volexity Ivanti Global Exploitation January 2024)(Citation: Mandiant Cutting Edge Part 2 January 2024)(Citation: Mandiant Cutting Edge Part 3 February 2024)", "external_references": [{"description": "Gurkok, C. et al. (2024, January 15). Ivanti Connect Secure VPN Exploitation Goes Global. Retrieved February 27, 2024.", "source_name": "Volexity Ivanti Global Exploitation January 2024", "url": "https://www.volexity.com/blog/2024/01/15/ivanti-connect-secure-vpn-exploitation-goes-global/"}, {"description": "Lin, M. et al. (2024, February 27). Cutting Edge, Part 3: Investigating Ivanti Connect Secure VPN Exploitation and Persistence Attempts. Retrieved March 1, 2024.", "source_name": "Mandiant Cutting Edge Part 3 February 2024", "url": "https://www.mandiant.com/resources/blog/investigating-ivanti-exploitation-persistence"}, {"description": "Lin, M. et al. (2024, January 31). Cutting Edge, Part 2: Investigating Ivanti Connect Secure VPN Zero-Day Exploitation. Retrieved February 27, 2024.", "source_name": "Mandiant Cutting Edge Part 2 January 2024", "url": "https://www.mandiant.com/resources/blog/investigating-ivanti-zero-day-exploitation"}, {"description": "McLellan, T. et al. (2024, January 12). Cutting Edge: Suspected APT Targets Ivanti Connect Secure VPN in New Zero-Day Exploitation. Retrieved February 27, 2024.", "source_name": "Mandiant Cutting Edge January 2024", "url": "https://www.mandiant.com/resources/blog/suspected-apt-targets-ivanti-zero-day"}, {"description": "Meltzer, M. et al. (2024, January 10). Active Exploitation of Two Zero-Day Vulnerabilities in Ivanti Connect Secure VPN. Retrieved February 27, 2024.", "source_name": "Volexity Ivanti Zero-Day Exploitation January 2024", "url": "https://www.volexity.com/blog/2024/01/10/active-exploitation-of-two-zero-day-vulnerabilities-in-ivanti-connect-secure-vpn/"}], "id": "relationship--9cf09dbc-7668-4c1c-8e57-01f9c082c80d", "modified": "2026-07-31T18:47:23.253Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--4fdd2487-26c1-494e-8702-ec5abe9aa1d9", "spec_version": "2.1", "target_ref": "attack-pattern--3f886f2a-874f-4333-b794-aa6075009b1c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5228', 0, 268, '09-mitre-attack', 'retrieved', '9E07D094C61AC458E387BEA155BCE523D4A8CADAC796FC74C12B473F1A5F3705', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
