VALUES ('doc-09-mitre-attack-p0-5236', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-06T18:26:48.392Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Cutting Edge](https://attack.mitre.org/campaigns/C0029), threat actors modified the JavaScript loaded by the Ivanti Connect Secure login page to capture credentials entered.(Citation: Volexity Ivanti Zero-Day Exploitation January 2024)", "external_references": [{"description": "Meltzer, M. et al. (2024, January 10). Active Exploitation of Two Zero-Day Vulnerabilities in Ivanti Connect Secure VPN. Retrieved February 27, 2024.", "source_name": "Volexity Ivanti Zero-Day Exploitation January 2024", "url": "https://www.volexity.com/blog/2024/01/10/active-exploitation-of-two-zero-day-vulnerabilities-in-ivanti-connect-secure-vpn/"}], "id": "relationship--d2881846-1061-4f1e-a9bf-4dfc6a7e4b41", "modified": "2026-07-31T18:47:23.426Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--4fdd2487-26c1-494e-8702-ec5abe9aa1d9", "spec_version": "2.1", "target_ref": "attack-pattern--69e5226d-05dc-4f15-95d7-44f5ed78d06e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5236', 0, 88, '09-mitre-attack', 'retrieved', 'A99122071CE4FC132A1D5EE49115C32A344EFE6A7F4C75DC5FEF3B6A2A8A63FF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
