VALUES ('doc-09-mitre-attack-p0-5239', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-12T18:34:54.477Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Cutting Edge](https://attack.mitre.org/campaigns/C0029), threat actors used a Base64-encoded Python script to write a patched version of the Ivanti Connect Secure `dsls` binary.(Citation: Mandiant Cutting Edge Part 2 January 2024)", "external_references": [{"description": "Lin, M. et al. (2024, January 31). Cutting Edge, Part 2: Investigating Ivanti Connect Secure VPN Zero-Day Exploitation. Retrieved February 27, 2024.", "source_name": "Mandiant Cutting Edge Part 2 January 2024", "url": "https://www.mandiant.com/resources/blog/investigating-ivanti-zero-day-exploitation"}], "id": "relationship--df5db6d7-a072-4d04-a638-843ac66234ef", "modified": "2026-07-31T18:47:23.503Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--4fdd2487-26c1-494e-8702-ec5abe9aa1d9", "spec_version": "2.1", "target_ref": "attack-pattern--0d91b3c0-5e50-47c3-949a-2a796f04d144", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5239', 0, 92, '09-mitre-attack', 'retrieved', 'FF60D532A4B5BA673E0CE92D2C55791E623B4208C2E13C8402BAA4658F59E45E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
