VALUES ('doc-09-mitre-attack-p0-5245', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-01-17T22:14:55.725Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0018](https://attack.mitre.org/campaigns/C0018), the threat actors used [netsh](https://attack.mitre.org/software/S0108) on a domain controller to ensure there was no existing firewall or to disable one.(Citation: Costa AvosLocker May 2022)", "external_references": [{"description": "Costa, F. (2022, May 1). RaaS AvosLocker Incident Response Analysis. Retrieved January 11, 2023.", "source_name": "Costa AvosLocker May 2022", "url": "https://www.linkedin.com/pulse/raas-avoslocker-incident-response-analysis-fl%C3%A1vio-costa?trk=articles_directory"}], "id": "relationship--10e7df4a-c95d-4b85-b044-84649fe3a6d1", "modified": "2026-07-31T18:47:22.864Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--519ee082-8ab6-439b-988f-a8a3f02c8d30", "spec_version": "2.1", "target_ref": "tool--5a63f900-5e7e-4928-a746-dd4558e1df71", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5245', 0, 78, '09-mitre-attack', 'retrieved', 'CB18F760FA4B8F80333A4DC19FE97098C5B5B8DDCBF96639F4ADA22F9A7B3897', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
