VALUES ('doc-09-mitre-attack-p0-5246', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-01-17T22:15:35.122Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0018](https://attack.mitre.org/campaigns/C0018), the threat actors used a PowerShell script to execute [Ping](https://attack.mitre.org/software/S0097) commands once every minute against a domain controller.(Citation: Costa AvosLocker May 2022)", "external_references": [{"description": "Costa, F. (2022, May 1). RaaS AvosLocker Incident Response Analysis. Retrieved January 11, 2023.", "source_name": "Costa AvosLocker May 2022", "url": "https://www.linkedin.com/pulse/raas-avoslocker-incident-response-analysis-fl%C3%A1vio-costa?trk=articles_directory"}], "id": "relationship--194b2a3c-ce1f-4326-a26f-fd998c94b947", "modified": "2026-07-31T18:47:22.876Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--519ee082-8ab6-439b-988f-a8a3f02c8d30", "spec_version": "2.1", "target_ref": "tool--b77b563c-34bb-4fb8-86a3-3694338f7b47", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5246', 0, 76, '09-mitre-attack', 'retrieved', 'C26422D38C12E450F0ABF1E640124AD3AE40C43FD91B9145D6A4857AED6C88E3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
