VALUES ('doc-09-mitre-attack-p0-5247', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-01-17T21:50:41.856Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0018](https://attack.mitre.org/campaigns/C0018), the threat actors exploited VMWare Horizon Unified Access Gateways that were vulnerable to several Log4Shell vulnerabilities, including CVE-2021-44228, CVE-2021-45046, CVE-2021-45105, and CVE-2021-44832.(Citation: Cisco Talos Avos Jun 2022)", "external_references": [{"description": "Venere, G. Neal, C. (2022, June 21). Avos ransomware group expands with new attack arsenal. Retrieved January 11, 2023.", "source_name": "Cisco Talos Avos Jun 2022", "url": "https://blog.talosintelligence.com/avoslocker-new-arsenal/"}], "id": "relationship--237d7c2e-503a-420c-bf94-047f5c42a646", "modified": "2026-07-31T18:47:22.903Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--519ee082-8ab6-439b-988f-a8a3f02c8d30", "spec_version": "2.1", "target_ref": "attack-pattern--3f886f2a-874f-4333-b794-aa6075009b1c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5247', 0, 87, '09-mitre-attack', 'retrieved', 'ADC9046285A754DF27A254C60C882D33CF727ACE2DB8C80DB28DA9E6AE81589E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
