VALUES ('doc-09-mitre-attack-p0-5248', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-02-14T20:59:15.805Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "For [C0018](https://attack.mitre.org/campaigns/C0018), the threat actors renamed a [Sliver](https://attack.mitre.org/software/S0633) payload to `vmware_kb.exe`.(Citation: Cisco Talos Avos Jun 2022)", "external_references": [{"description": "Venere, G. Neal, C. (2022, June 21). Avos ransomware group expands with new attack arsenal. Retrieved January 11, 2023.", "source_name": "Cisco Talos Avos Jun 2022", "url": "https://blog.talosintelligence.com/avoslocker-new-arsenal/"}], "id": "relationship--3564dc8e-09d0-4855-8a90-d4c28a9488e5", "modified": "2026-07-31T18:47:22.925Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--519ee082-8ab6-439b-988f-a8a3f02c8d30", "spec_version": "2.1", "target_ref": "attack-pattern--1c4e5d32-1fe9-4116-9d9d-59e3925bd6a2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5248', 0, 74, '09-mitre-attack', 'retrieved', '47F72FCADEA614629FF891E662FD10492CBB180A57B5F0566226ED61BF39C772', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
