VALUES ('doc-09-mitre-attack-p0-5250', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-01-17T22:04:06.267Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0018](https://attack.mitre.org/campaigns/C0018), the threat actors opened a variety of ports to establish RDP connections, including ports 28035, 32467, 41578, and 46892.(Citation: Costa AvosLocker May 2022)", "external_references": [{"description": "Costa, F. (2022, May 1). RaaS AvosLocker Incident Response Analysis. Retrieved January 11, 2023.", "source_name": "Costa AvosLocker May 2022", "url": "https://www.linkedin.com/pulse/raas-avoslocker-incident-response-analysis-fl%C3%A1vio-costa?trk=articles_directory"}], "id": "relationship--4bc4f37e-5cdd-4def-a997-1cbb37975a8f", "modified": "2026-07-31T18:47:22.964Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--519ee082-8ab6-439b-988f-a8a3f02c8d30", "spec_version": "2.1", "target_ref": "attack-pattern--eb062747-2193-45de-8fa2-e62549c37ddf", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5250', 0, 77, '09-mitre-attack', 'retrieved', '0E7C6A0BF02D2319F7685ECAEC1C0279CDAD1DDE5EF130F5555E720DF22DCCB7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
