VALUES ('doc-09-mitre-attack-p0-5262', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-02-14T21:49:54.159Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "For [C0018](https://attack.mitre.org/campaigns/C0018), the threat actors acquired a variety of open source tools, including [Mimikatz](https://attack.mitre.org/software/S0002), [Sliver](https://attack.mitre.org/software/S0633), SoftPerfect Network Scanner, AnyDesk, and PDQ Deploy.(Citation: Cisco Talos Avos Jun 2022)(Citation: Costa AvosLocker May 2022)", "external_references": [{"description": "Costa, F. (2022, May 1). RaaS AvosLocker Incident Response Analysis. Retrieved January 11, 2023.", "source_name": "Costa AvosLocker May 2022", "url": "https://www.linkedin.com/pulse/raas-avoslocker-incident-response-analysis-fl%C3%A1vio-costa?trk=articles_directory"}, {"description": "Venere, G. Neal, C. (2022, June 21). Avos ransomware group expands with new attack arsenal. Retrieved January 11, 2023.", "source_name": "Cisco Talos Avos Jun 2022", "url": "https://blog.talosintelligence.com/avoslocker-new-arsenal/"}], "id": "relationship--c0c1a394-23db-44cf-a922-89e10ba13ec6", "modified": "2026-07-31T18:47:23.251Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--519ee082-8ab6-439b-988f-a8a3f02c8d30", "spec_version": "2.1", "target_ref": "attack-pattern--a2fdce72-04b2-409a-ac10-cc1695f4fce0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5262', 0, 111, '09-mitre-attack', 'retrieved', '4004AB4866E96C58A07B06B8EC0AC70B912B6089B22A28B1FE56BEC787DEC195', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
