VALUES ('doc-09-mitre-attack-p0-5266', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-01-24T20:31:29.234Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0018](https://attack.mitre.org/campaigns/C0018), [AvosLocker](https://attack.mitre.org/software/S1053) was disguised using the victim company name as the filename.(Citation: Cisco Talos Avos Jun 2022)", "external_references": [{"description": "Venere, G. Neal, C. (2022, June 21). Avos ransomware group expands with new attack arsenal. Retrieved January 11, 2023.", "source_name": "Cisco Talos Avos Jun 2022", "url": "https://blog.talosintelligence.com/avoslocker-new-arsenal/"}], "id": "relationship--ed149b2f-6743-4d06-b869-158c0f96746e", "modified": "2026-07-31T18:47:23.321Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--519ee082-8ab6-439b-988f-a8a3f02c8d30", "spec_version": "2.1", "target_ref": "attack-pattern--42e8de7b-37b2-4258-905a-6897815e58e0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5266', 0, 76, '09-mitre-attack', 'retrieved', '31DD36EFD21148AF0E18A1D8C8190607ECAEF8B08049A24D6B9BA04FC390CCAE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
