VALUES ('doc-09-mitre-attack-p0-5268', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-01-24T20:43:38.347Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0018](https://attack.mitre.org/campaigns/C0018), the threat actors used `rundll32` to run [Mimikatz](https://attack.mitre.org/software/S0002).(Citation: Costa AvosLocker May 2022)", "external_references": [{"description": "Costa, F. (2022, May 1). RaaS AvosLocker Incident Response Analysis. Retrieved January 11, 2023.", "source_name": "Costa AvosLocker May 2022", "url": "https://www.linkedin.com/pulse/raas-avoslocker-incident-response-analysis-fl%C3%A1vio-costa?trk=articles_directory"}], "id": "relationship--fe26276a-d93c-400b-8907-1fcc9415ee38", "modified": "2026-07-31T18:47:23.364Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--519ee082-8ab6-439b-988f-a8a3f02c8d30", "spec_version": "2.1", "target_ref": "attack-pattern--045d0922-2310-4e60-b5e4-3302302cb3c5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5268', 0, 66, '09-mitre-attack', 'retrieved', '9680F289FC801C16B847E15C5506DE85860C0F5044ABE779B0110A65CD0697DA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
