VALUES ('doc-09-mitre-attack-p0-5269', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-07-19T18:25:21.802Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Water Curupira Pikabot Distribution](https://attack.mitre.org/campaigns/C0037) delivered [Pikabot](https://attack.mitre.org/software/S1145) installers as password-protected ZIP files containing heavily obfuscated JavaScript, or IMG files containing an LNK mimicking a Word document and a malicious DLL.(Citation: TrendMicro Pikabot 2024)", "external_references": [{"description": "Shinji Robert Arasawa, Joshua Aquino, Charles Steven Derion, Juhn Emmanuel Atanque, Francisrey Joshua Castillo, John Carlo Marquez, Henry Salcedo, John Rainier Navato, Arianne Dela Cruz, Raymart Yambot & Ian Kenefick. (2024, January 9). Black Basta-Affiliated Water Curupira’s Pikabot Spam Campaign. Retrieved July 17, 2024.", "source_name": "TrendMicro Pikabot 2024", "url": "https://www.trendmicro.com/en_us/research/24/a/a-look-into-pikabot-spam-wave-campaign.html"}], "id": "relationship--0b4b6ab2-df1f-4142-bbfa-5f26980d805b", "modified": "2026-07-31T18:47:23.283Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--57541e3b-657e-463a-a4ab-ca08d7ea9965", "spec_version": "2.1", "target_ref": "attack-pattern--232b7f21-adf9-4b42-b936-b9d6f7df856e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5269', 0, 113, '09-mitre-attack', 'retrieved', '9A9A7A2103644DC07AAB75DEE755770E35D41F16D9055C561EC347E4ED52EA26', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
