VALUES ('doc-09-mitre-attack-p0-5270', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-07-19T18:28:19.517Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Water Curupira Pikabot Distribution](https://attack.mitre.org/campaigns/C0037) installation via JavaScript will launch follow-on commands via cmd.exe.(Citation: TrendMicro Pikabot 2024)", "external_references": [{"description": "Shinji Robert Arasawa, Joshua Aquino, Charles Steven Derion, Juhn Emmanuel Atanque, Francisrey Joshua Castillo, John Carlo Marquez, Henry Salcedo, John Rainier Navato, Arianne Dela Cruz, Raymart Yambot & Ian Kenefick. (2024, January 9). Black Basta-Affiliated Water Curupira’s Pikabot Spam Campaign. Retrieved July 17, 2024.", "source_name": "TrendMicro Pikabot 2024", "url": "https://www.trendmicro.com/en_us/research/24/a/a-look-into-pikabot-spam-wave-campaign.html"}], "id": "relationship--2e07c275-4a34-4249-bbd5-7342ddcfa759", "modified": "2026-07-31T18:47:23.314Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--57541e3b-657e-463a-a4ab-ca08d7ea9965", "spec_version": "2.1", "target_ref": "attack-pattern--d1fcf083-a721-4223-aedf-bf8960798d62", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5270', 0, 97, '09-mitre-attack', 'retrieved', 'B735A13D9A7774349FE7BFB21968283A1853FB021336649AC149B67A5AA9B0B9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
