VALUES ('doc-09-mitre-attack-p0-5295', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-02-18T16:45:40.066Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [J-magic Campaign](https://attack.mitre.org/campaigns/C0050) campaign, threat actors used open-source malware post-compromise including a custom variant of the cd00r backdoor.(Citation: Lumen J-Magic JAN 2025)", "external_references": [{"description": "Black Lotus Labs. (2025, January 23). The J-Magic Show: Magic Packets and Where to find them. Retrieved February 17, 2025.", "source_name": "Lumen J-Magic JAN 2025", "url": "https://blog.lumen.com/the-j-magic-show-magic-packets-and-where-to-find-them/"}], "id": "relationship--6cfe5ceb-c2c2-4745-8611-a3b9ebc4ad83", "modified": "2026-07-31T18:47:23.868Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--58c4fd17-88f5-433a-8242-e9cac31f3c45", "spec_version": "2.1", "target_ref": "attack-pattern--7807d3a4-a885-4639-a786-c1ed41484970", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5295', 0, 81, '09-mitre-attack', 'retrieved', 'B3AADDCB7B6715530DB0848FB3E2EF6E5D120FEE91B43E25EAE378AAF1DB9194', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
