VALUES ('doc-09-mitre-attack-p0-5296', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-02-18T17:00:16.554Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [J-magic Campaign](https://attack.mitre.org/campaigns/C0050), threat actors used self-signed certificates on VPS C2 infrastructure.(Citation: Lumen J-Magic JAN 2025)", "external_references": [{"description": "Black Lotus Labs. (2025, January 23). The J-Magic Show: Magic Packets and Where to find them. Retrieved February 17, 2025.", "source_name": "Lumen J-Magic JAN 2025", "url": "https://blog.lumen.com/the-j-magic-show-magic-packets-and-where-to-find-them/"}], "id": "relationship--ce798fe6-023d-42f7-a44a-6f0ef0b58dff", "modified": "2026-07-31T18:47:23.884Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--58c4fd17-88f5-433a-8242-e9cac31f3c45", "spec_version": "2.1", "target_ref": "attack-pattern--1cec9319-743b-4840-bb65-431547bce82a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5296', 0, 75, '09-mitre-attack', 'retrieved', '22CAF6A09F75BB57289A6B1B4C343122728D7ACAD25BA091941F69FBEF9695CE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
