VALUES ('doc-09-mitre-attack-p0-5297', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-20T19:20:04.367Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [Anthropic AI-orchestrated Campaign](https://attack.mitre.org/campaigns/C0062), the adversary used Claude Code to deploy a custom exploit payload targeting an identified SSRF vulnerability to gain initial access to a targeted environment.(Citation: Anthropic AI Orchestrated Campaign NOV 2025)", "external_references": [{"description": "Anthropic. (2025, November). Disrupting the first reported AI-orchestrated cyber espionage campaign. Retrieved April 20, 2026.", "source_name": "Anthropic AI Orchestrated Campaign NOV 2025", "url": "https://assets.anthropic.com/m/ec212e6566a0d47/original/Disrupting-the-first-reported-AI-orchestrated-cyber-espionage-campaign.pdf"}], "id": "relationship--0365ae71-f035-48af-bed4-7609e7029804", "modified": "2026-07-31T18:47:24.160Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--590cd5b0-2421-4158-84a2-db13b5db02a3", "spec_version": "2.1", "target_ref": "attack-pattern--3f886f2a-874f-4333-b794-aa6075009b1c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5297', 0, 90, '09-mitre-attack', 'retrieved', '8F1353F4238D5D6E4253E98B3F812C7F977D451D286D6A7E3E899B44FE0840D8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
