VALUES ('doc-09-mitre-attack-p0-5298', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-20T19:16:30.566Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [Anthropic AI-orchestrated Campaign](https://attack.mitre.org/campaigns/C0062), the adversary obtained open-source penetration testing tools including network scanners, database exploitation frameworks, password crackers, and binary analysis suites.(Citation: Anthropic AI Orchestrated Campaign NOV 2025)", "external_references": [{"description": "Anthropic. (2025, November). Disrupting the first reported AI-orchestrated cyber espionage campaign. Retrieved April 20, 2026.", "source_name": "Anthropic AI Orchestrated Campaign NOV 2025", "url": "https://assets.anthropic.com/m/ec212e6566a0d47/original/Disrupting-the-first-reported-AI-orchestrated-cyber-espionage-campaign.pdf"}], "id": "relationship--312f2cb6-8528-4404-857a-c8c685d7e179", "modified": "2026-07-31T18:47:24.183Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--590cd5b0-2421-4158-84a2-db13b5db02a3", "spec_version": "2.1", "target_ref": "attack-pattern--a2fdce72-04b2-409a-ac10-cc1695f4fce0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5298', 0, 85, '09-mitre-attack', 'retrieved', '5468AD7E59E2285144BD5868B7816BD5057A788AB2BB8058840C954E0B9993AE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
