VALUES ('doc-09-mitre-attack-p0-5308', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-20T19:18:52.374Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [Anthropic AI-orchestrated Campaign](https://attack.mitre.org/campaigns/C0062), the adversary used Claude Code to research exploitation techniques for an identified SSRF vulnerability, to generate a tailored custom attack payload, and to develop a full exploit chain prior to deployment.(Citation: Anthropic AI Orchestrated Campaign NOV 2025)", "external_references": [{"description": "Anthropic. (2025, November). Disrupting the first reported AI-orchestrated cyber espionage campaign. Retrieved April 20, 2026.", "source_name": "Anthropic AI Orchestrated Campaign NOV 2025", "url": "https://assets.anthropic.com/m/ec212e6566a0d47/original/Disrupting-the-first-reported-AI-orchestrated-cyber-espionage-campaign.pdf"}], "id": "relationship--82a8a34c-a439-463a-822b-9305e30b0b32", "modified": "2026-07-31T18:47:24.411Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--590cd5b0-2421-4158-84a2-db13b5db02a3", "spec_version": "2.1", "target_ref": "attack-pattern--bbc3cba7-84ae-410d-b18b-16750731dfa2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5308', 0, 97, '09-mitre-attack', 'retrieved', '98A9D63B7A701DB779FB79E8D9798035A2850255CBC94333A7BB3AB81A0050A2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
