VALUES ('doc-09-mitre-attack-p0-5321', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-23T23:10:31.442Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [Anthropic AI-orchestrated Campaign](https://attack.mitre.org/campaigns/C0062), the adversary tasked Claude Code to query databases and systems in order to identify proprietary information, including system configurations and database types.(Citation: Anthropic AI Orchestrated Campaign NOV 2025)", "external_references": [{"description": "Anthropic. (2025, November). Disrupting the first reported AI-orchestrated cyber espionage campaign. Retrieved April 20, 2026.", "source_name": "Anthropic AI Orchestrated Campaign NOV 2025", "url": "https://assets.anthropic.com/m/ec212e6566a0d47/original/Disrupting-the-first-reported-AI-orchestrated-cyber-espionage-campaign.pdf"}], "id": "relationship--cd18fa85-3b0c-4201-b85d-92dfaf91eb5a", "modified": "2026-07-31T18:47:24.729Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--590cd5b0-2421-4158-84a2-db13b5db02a3", "spec_version": "2.1", "target_ref": "attack-pattern--354a7f88-63fb-41b5-a801-ce3b377b36f1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5321', 0, 88, '09-mitre-attack', 'retrieved', 'C93D52DC2F3B5ADC1710C4F33E7FE285BD164B46028414129C0BEB5A7768E45B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
