VALUES ('doc-09-mitre-attack-p0-5322', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-23T23:07:35.618Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [Anthropic AI-orchestrated Campaign](https://attack.mitre.org/campaigns/C0062), the adversary used Claude Code to map internal network architecture and access relationships.(Citation: Anthropic AI Orchestrated Campaign NOV 2025)", "external_references": [{"description": "Anthropic. (2025, November). Disrupting the first reported AI-orchestrated cyber espionage campaign. Retrieved April 20, 2026.", "source_name": "Anthropic AI Orchestrated Campaign NOV 2025", "url": "https://assets.anthropic.com/m/ec212e6566a0d47/original/Disrupting-the-first-reported-AI-orchestrated-cyber-espionage-campaign.pdf"}], "id": "relationship--ecdd4a9f-c89b-444f-ae27-c51c5714b60c", "modified": "2026-07-31T18:47:24.751Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--590cd5b0-2421-4158-84a2-db13b5db02a3", "spec_version": "2.1", "target_ref": "attack-pattern--7e150503-88e7-4861-866b-ff1ac82c4475", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5322', 0, 79, '09-mitre-attack', 'retrieved', '0D8C0F4A9902448D27381DA47CC3EBF0972BFD40A4BD8C46DCAA02C7F1A75AB2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
