VALUES ('doc-09-mitre-attack-p0-5327', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-20T19:54:31.643Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0021](https://attack.mitre.org/campaigns/C0021), the threat actors lured users into clicking a malicious link which led to the download of a ZIP archive containing a malicious .LNK file.(Citation: FireEye APT29 Nov 2018)", "external_references": [{"description": "Dunwoody, M., et al. (2018, November 19). Not So Cozy: An Uncomfortable Examination of a Suspected APT29 Phishing Campaign. Retrieved November 27, 2018.", "source_name": "FireEye APT29 Nov 2018", "url": "https://www.fireeye.com/blog/threat-research/2018/11/not-so-cozy-an-uncomfortable-examination-of-a-suspected-apt29-phishing-campaign.html"}], "id": "relationship--5610e19c-de2e-4b9d-9e10-776e94528b0d", "modified": "2026-07-31T18:47:24.365Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--712e38c3-a656-426a-9b3b-a6bfb63294c6", "spec_version": "2.1", "target_ref": "attack-pattern--ef67e13e-5598-4adc-bdb2-998225874fa9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5327', 0, 91, '09-mitre-attack', 'retrieved', '1DF0EF9D7F7CB65ACFBF1981BC915E93E69279C3E5F1846DF782FC5789CECA32', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
