VALUES ('doc-09-mitre-attack-p0-5374', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-29T19:03:42.434Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0015](https://attack.mitre.org/campaigns/C0015), the threat actors loaded DLLs via `rundll32` using the `svchost` process.(Citation: DFIR Conti Bazar Nov 2021)", "external_references": [{"description": "DFIR Report. (2021, November 29). CONTInuing the Bazar Ransomware Story. Retrieved September 29, 2022.", "source_name": "DFIR Conti Bazar Nov 2021", "url": "https://thedfirreport.com/2021/11/29/continuing-the-bazar-ransomware-story/"}], "id": "relationship--511ed53b-8445-4da7-8890-49d1b4e98077", "modified": "2026-07-31T18:47:25.305Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--78068e68-4124-4243-b6f4-76e4e5be8a06", "spec_version": "2.1", "target_ref": "attack-pattern--045d0922-2310-4e60-b5e4-3302302cb3c5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5374', 0, 71, '09-mitre-attack', 'retrieved', '976C31457EE3D4ECABFAF80C57AA3F242FC0C16D0433C5DCF58E17301FAA5C0E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
