VALUES ('doc-09-mitre-attack-p0-5375', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-29T16:52:41.309Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "For [C0015](https://attack.mitre.org/campaigns/C0015), security researchers assessed the threat actors likely used a phishing campaign to distribute a weaponized attachment to victims.(Citation: DFIR Conti Bazar Nov 2021)", "external_references": [{"description": "DFIR Report. (2021, November 29). CONTInuing the Bazar Ransomware Story. Retrieved September 29, 2022.", "source_name": "DFIR Conti Bazar Nov 2021", "url": "https://thedfirreport.com/2021/11/29/continuing-the-bazar-ransomware-story/"}], "id": "relationship--538eb3a4-466e-42d0-9f12-bd9b6de0abe4", "modified": "2026-07-31T18:47:25.321Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--78068e68-4124-4243-b6f4-76e4e5be8a06", "spec_version": "2.1", "target_ref": "attack-pattern--2e34237d-8574-43f6-aace-ae2915de8597", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5375', 0, 78, '09-mitre-attack', 'retrieved', '5D988BA27AE176F5D0136DD4427FBBD3CEC80BE1F63B562F79D52F9D443F1DB3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
