VALUES ('doc-09-mitre-attack-p0-5376', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-29T19:56:25.812Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0015](https://attack.mitre.org/campaigns/C0015), the threat actors obtained files and data from the compromised network.(Citation: DFIR Conti Bazar Nov 2021)", "external_references": [{"description": "DFIR Report. (2021, November 29). CONTInuing the Bazar Ransomware Story. Retrieved September 29, 2022.", "source_name": "DFIR Conti Bazar Nov 2021", "url": "https://thedfirreport.com/2021/11/29/continuing-the-bazar-ransomware-story/"}], "id": "relationship--576f0fb4-4cd7-467b-9208-3977321705e4", "modified": "2026-07-31T18:47:25.335Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--78068e68-4124-4243-b6f4-76e4e5be8a06", "spec_version": "2.1", "target_ref": "attack-pattern--3c4a2599-71ee-4405-ba1e-0e28414b4bc5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5376', 0, 71, '09-mitre-attack', 'retrieved', 'D63BF6F114E0EC5AAEA8FA2FD79C6750014C46016BF8A6F1C75264AC972BC3EA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
