VALUES ('doc-09-mitre-attack-p0-5377', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-29T19:17:03.296Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0015](https://attack.mitre.org/campaigns/C0015), the threat actors used the command `net localgroup \"adminstrator\" ` to identify accounts with local administrator rights.(Citation: DFIR Conti Bazar Nov 2021)", "external_references": [{"description": "DFIR Report. (2021, November 29). CONTInuing the Bazar Ransomware Story. Retrieved September 29, 2022.", "source_name": "DFIR Conti Bazar Nov 2021", "url": "https://thedfirreport.com/2021/11/29/continuing-the-bazar-ransomware-story/"}], "id": "relationship--5968f7a6-a300-4a1b-9a4e-655e9300392b", "modified": "2026-07-31T18:47:25.348Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--78068e68-4124-4243-b6f4-76e4e5be8a06", "spec_version": "2.1", "target_ref": "attack-pattern--a01bf75f-00b2-4568-a58f-565ff9bf202b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5377', 0, 77, '09-mitre-attack', 'retrieved', '77DD6CBE84DFE14973068BF3DEAC9E0F1C8E347866F46B57F090C9DD8A2D3B26', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
