VALUES ('doc-09-mitre-attack-p0-5391', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-29T19:26:04.122Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0015](https://attack.mitre.org/campaigns/C0015), the threat actors used the command `net view /all time` to gather the local time of a compromised network.(Citation: DFIR Conti Bazar Nov 2021)", "external_references": [{"description": "DFIR Report. (2021, November 29). CONTInuing the Bazar Ransomware Story. Retrieved September 29, 2022.", "source_name": "DFIR Conti Bazar Nov 2021", "url": "https://thedfirreport.com/2021/11/29/continuing-the-bazar-ransomware-story/"}], "id": "relationship--c5e582d2-aea4-4828-8b9c-5bfe1ca72504", "modified": "2026-07-31T18:47:25.636Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--78068e68-4124-4243-b6f4-76e4e5be8a06", "spec_version": "2.1", "target_ref": "attack-pattern--f3c544dc-673c-4ef3-accb-53229f1ae077", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5391', 0, 79, '09-mitre-attack', 'retrieved', '1D2FF40E1ADCEC09AC8C99CDBF2CEC9EF287A699E0A92F08EB024DD191B89276', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
