VALUES ('doc-09-mitre-attack-p0-5407', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-23T18:51:26.831Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "For [Operation Ghost](https://attack.mitre.org/campaigns/C0023), [APT29](https://attack.mitre.org/groups/G0016) used [MiniDuke](https://attack.mitre.org/software/S0051) as a second-stage backdoor.(Citation: ESET Dukes October 2019)", "external_references": [{"description": "Faou, M., Tartare, M., Dupuy, T. (2019, October). OPERATION GHOST. Retrieved September 23, 2020.", "source_name": "ESET Dukes October 2019", "url": "https://www.welivesecurity.com/wp-content/uploads/2019/10/ESET_Operation_Ghost_Dukes.pdf"}], "id": "relationship--60ee610e-087d-4515-9c42-9a60cc04d683", "modified": "2026-07-31T18:47:25.280Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--7854c1a0-f06c-4876-98a4-4bbd34751b05", "spec_version": "2.1", "target_ref": "malware--5e7ef1dc-7fb6-4913-ac75-e06113b59e0c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5407', 0, 66, '09-mitre-attack', 'retrieved', 'D3719BD1CAE9EAB9422DC1F792554206BA12EEC4A8FFD624C84F62D1C707AA1A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
