VALUES ('doc-09-mitre-attack-p0-5417', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-11-25T22:16:25.337Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Juicy Mix](https://attack.mitre.org/campaigns/C0044), [OilRig](https://attack.mitre.org/groups/G0049) used a script to concatenate and deobfuscate encoded strings in [Mango](https://attack.mitre.org/software/S1169).(Citation: ESET OilRig Campaigns Sep 2023)", "external_references": [{"description": "Hromcova, Z. and Burgher, A. (2023, September 21). OilRig’s Outer Space and Juicy Mix: Same ol’ rig, new drill pipes. Retrieved November 21, 2024.", "source_name": "ESET OilRig Campaigns Sep 2023", "url": "https://www.welivesecurity.com/en/eset-research/oilrigs-outer-space-juicy-mix-same-ol-rig-new-drill-pipes/"}], "id": "relationship--017c304d-dec3-4d0e-ac60-8acfbfe41a7c", "modified": "2026-07-31T21:13:47.592Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--7ab2f1a1-26af-4204-ad84-d640fde391da", "spec_version": "2.1", "target_ref": "attack-pattern--3ccef7ae-cb5e-48f6-8302-897105fbf55c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5417', 0, 83, '09-mitre-attack', 'retrieved', '4D2A6636AD7208933FC62FBC9E48AF0AFFD4B70F3F3E782797B5E6F6FF9F4D0F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
