VALUES ('doc-09-mitre-attack-p0-5425', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-11-25T21:08:37.101Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Juicy Mix](https://attack.mitre.org/campaigns/C0044), [OilRig](https://attack.mitre.org/groups/G0049) used browser data and credential stealer tools to stage stolen files named Cupdate, Eupdate, and IUpdate in the %TEMP% directory.(Citation: ESET OilRig Campaigns Sep 2023)", "external_references": [{"description": "Hromcova, Z. and Burgher, A. (2023, September 21). OilRig’s Outer Space and Juicy Mix: Same ol’ rig, new drill pipes. Retrieved November 21, 2024.", "source_name": "ESET OilRig Campaigns Sep 2023", "url": "https://www.welivesecurity.com/en/eset-research/oilrigs-outer-space-juicy-mix-same-ol-rig-new-drill-pipes/"}], "id": "relationship--9bb68fb7-931e-4d24-a042-c6545fb8167f", "modified": "2026-07-31T21:13:47.681Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--7ab2f1a1-26af-4204-ad84-d640fde391da", "spec_version": "2.1", "target_ref": "attack-pattern--1c34f7aa-9341-4a48-bfab-af22e51aca6c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5425', 0, 92, '09-mitre-attack', 'retrieved', 'E4125F9C09183EAE5956385DBC4D84D79DB0503B9FB3A76BFD86F8F5D73B76F8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
